// Concept-specific independent explanations for formerly link-only sections.
// Keys retain the original page and heading; no generic placeholder is generated.
export const sectionLibrary={};
function add(id,title,...texts){(sectionLibrary[id]??={})[title]=texts.map(text=>({type:'p',text}));}
add('1-1-1-2','포사체의 운동량 변화 모의실험',
 '공기 저항을 무시한 포물선 운동에서는 물체에 아래 방향의 중력만 작용한다. 수평 운동량은 일정하고 수직 운동량은 시간에 따라 같은 비율로 감소한다. 최고점에서도 수평 속도와 운동량은 남아 있으며 수직 성분만 0이 된다.',
 '발사각을 바꾸면 처음의 수평·수직 운동량이 달라진다. 여러 시각의 두 성분을 기록하여 수평 성분이 일정한지, 수직 성분의 시간 그래프 기울기가 −mg인지 비교하자. 같은 질량과 발사 속도에서 각도를 높이면 상승 시간이 길어지지만 수평 속도는 작아진다.');
add('1-1-4-1','탄성충돌과 비탄성충돌',
 '충돌 시간 동안 외부에서 받는 충격량이 무시될 정도로 작으면 두 물체의 전체 운동량은 보존된다. 탄성충돌에서는 충돌 전후의 전체 운동에너지도 같지만, 비탄성충돌에서는 일부가 변형·열·소리와 내부 운동에너지로 바뀐다.',
 '비탄성충돌에서도 에너지 자체가 사라지는 것은 아니다. 운동량과 운동에너지는 서로 다른 보존 조건이므로 두 물체의 속도가 각각 달라질 수 있다. 닫힌 계의 운동량을 비교할 때에는 물체의 운동량을 방향을 가진 벡터로 더해야 한다.');
add('1-1-4-2','1차원 충돌의 모의실험',
 '같은 직선 위에서 충돌하는 두 물체는 질량, 충돌 전 속도, 반발계수를 바꾸어 비교할 수 있다. 반발계수는 충돌 후 서로 멀어지는 상대속력과 충돌 전 서로 접근하는 상대속력의 비다. 보통 0에서 1 사이의 값을 갖는다.',
 '동일한 질량의 두 물체가 탄성충돌하고 하나가 처음 정지했다면 움직이던 물체가 멈추고 다른 물체가 그 속도로 움직인다. 질량을 다르게 하면 결과가 바뀐다. 각 속도만 보지 말고 충돌 전후 전체 운동량과 전체 운동에너지를 함께 계산하자.');
add('1-1-4-3','비탄성충돌',
 '충돌 뒤 두 물체가 붙어 함께 움직이는 경우를 완전비탄성충돌이라 한다. 외부 충격량이 없다면 공통 속도는 충돌 전 전체 운동량을 전체 질량으로 나눈 값이다. 질량중심의 운동은 유지되고 상대운동에 쓰이던 에너지가 내부에너지 등으로 바뀐다.',
 '두 물체가 충돌 후 모두 정지할 수도 있지만 이는 충돌 전 전체 운동량이 0인 경우에 한한다. 일반적으로 운동량이 0이 아니면 붙은 물체도 움직여야 한다. 충돌 전후 운동에너지의 차이를 계산하면 거시적인 운동에서 다른 형태로 바뀐 에너지를 알 수 있다.');
add('1-1-5-1','2차원 충돌 모의실험',
 '평면에서의 충돌은 운동량보존법칙을 가로·세로 성분에 각각 적용한다. 마찰과 회전을 무시한 매끄러운 원형 물체끼리의 충돌에서는 접촉점의 충격량이 두 중심을 잇는 방향으로 작용한다. 그 방향에 수직인 상대속도 성분은 바뀌지 않는다.',
 '입사 위치와 속도를 바꾸면 접촉 순간의 중심선 방향이 달라져 산란각도 달라진다. 충돌 전후 각 물체의 속도 화살표와 전체 운동량 화살표를 비교하자. 동일 질량의 탄성충돌에서 하나가 정지했던 경우, 두 물체가 모두 움직인다면 충돌 후 속도 방향은 서로 직각이다.');
add('1-1-5-2','지면에서 되튀는 물체의 운동',
 '공이 지면에 충돌하면 짧은 시간 동안 큰 접촉력이 작용하여 수직 운동량이 바뀐다. 지구까지 포함한 계의 운동량은 보존되지만 지구의 질량이 매우 커서 지구의 속도 변화는 거의 보이지 않는다. 매끄러운 평면에서는 접선방향의 속도는 유지된다.',
 '반발계수가 1이면 수직 속도의 크기가 같고 방향만 반대가 된다. 반발계수가 작으면 되튀는 높이가 낮아진다. 공기 저항이 없고 수직으로 튀는 경우 연속한 최대 높이의 비는 반발계수의 제곱이다. 실제 공에서는 접촉 마찰과 회전도 결과에 영향을 준다.');
add('1-1-5-3','충돌을 통한 질량추정',
 '외부 힘의 충격량을 무시할 수 있으면 두 공의 속도 변화는 질량에 반비례한다. 한 공의 운동량 증가와 다른 공의 운동량 감소가 같기 때문이다. 따라서 충돌 전후 속도 벡터를 측정하면 두 공의 질량비를 추정할 수 있다.',
 '겉보기 공의 크기가 질량을 곧바로 정해 주지는 않는다. 질량을 알아내려는 실험에서 이미 질량을 곱한 운동량 표시를 사용하면 결론이 입력 정보에 의존하게 된다. 속도만으로 먼저 추정하고 여러 충돌의 결과를 대조해야 한다.');
add('1-1-5-3','당구의 모의실험',
 '여러 공이 벽과 다른 공에 부딪히는 계에서는 연속된 충돌을 각각의 두 물체 충돌로 분석할 수 있다. 같은 질량의 매끄러운 공에서는 접촉 중심선 방향의 속도 성분이 교환되므로 처음의 운동이 여러 공으로 전달된다.',
 '실제 당구에서는 공의 회전, 공끼리의 마찰, 바닥 마찰, 쿠션의 반발 특성이 중요하다. 회전을 제외한 모형은 운동량 전달의 기본 관계를 보여 주지만 스핀을 준 실제 공의 궤적을 그대로 예측하지 않는다. 공의 수와 초기 방향을 바꾸면서 운동량이 어떻게 나누어지는지 살펴보자.');
add('1-2-1-1','진동',
 '물체가 평형위치 주변에서 왕복하는 운동을 진동이라 한다. 평형위치에서 벗어나면 되돌아가는 방향의 복원력이 작용하고, 관성 때문에 물체가 평형위치를 지나쳐 반대쪽으로 움직이면서 운동이 반복된다. 한 번 반복하는 시간은 주기다.',
 '모든 진동이 정현파인 것은 아니다. 탄성 막대의 떨림, 진자의 작은 흔들림, 용수철의 운동은 조건에 따라 조화진동으로 근사할 수 있다. 마찰과 저항이 있으면 진폭이 감소하고, 외부에서 주기적인 힘을 가하면 강제진동이 나타난다.');
add('1-2-1-1','퍼텐셜과 진동',
 '퍼텐셜 에너지 곡선이 극소인 곳은 안정한 평형위치다. 그 주변에서 물체를 옮기면 에너지가 증가하고 힘은 곡선의 기울기와 반대 방향으로 작용한다. 총에너지가 주어진 보존계에서 물체는 퍼텐셜이 총에너지보다 낮은 영역 안에서 운동한다.',
 '총에너지와 퍼텐셜이 같은 지점에서는 운동에너지가 0이 되어 진행 방향이 바뀐다. 우물이 이차함수에 가까우면 작은 진동은 조화진동이고, 우물의 모양이 다르면 속도와 주기의 진폭 의존성이 달라진다. 이중 우물에서는 에너지가 중앙 장벽보다 높은지에 따라 두 우물 사이를 오갈 수 있는지가 달라진다.');
add('1-2-3-1','연결된 진동자',
 '서로 연결된 질점은 각자의 변위뿐 아니라 이웃의 변위에 따라서도 힘을 받는다. 따라서 한 질점의 운동방정식만 독립적으로 풀 수 없고 여러 방정식을 동시에 풀어야 한다. 분자의 원자 진동이나 고체의 격자 진동이 결합 진동자의 예다.',
 '각 질점은 여러 정상 모드가 중첩된 운동을 할 수 있다. 정상 모드 하나에서는 모든 질점이 같은 주파수로 진동하며 상대적인 진폭과 위상 관계가 유지된다. 한 질점만 옮겨 놓으면 보통 여러 모드를 동시에 자극하여 진폭이 복잡하게 변한다.');
add('1-2-3-2','연결된 진동자 모의실험',
 '양 끝이 고정되고 같은 질량의 두 질점이 세 용수철로 연결된 계를 생각하자. 바깥의 두 용수철이 같다면 두 질점이 같은 방향으로 움직이는 모드와 반대 방향으로 움직이는 모드를 구별할 수 있다. 가운데 연결은 반대 방향 모드에서 더 크게 변형된다.',
 '두 질점을 같은 크기·같은 방향으로 옮긴 경우와 같은 크기·반대 방향으로 옮긴 경우를 비교하자. 한 질점만 옮기는 조건은 두 모드의 중첩이다. 질량이나 연결 강도를 바꾸면 고유진동수가 달라지고, 감쇠가 없다면 에너지가 질점 사이에 오가면서 전체 에너지는 보존된다.');
add('1-2-4-2','2차원 진동',
 '서로 수직인 두 방향의 운동이 독립적인 조화진동이라면 두 변위를 함께 그린 궤적은 리사주 곡선이 된다. 각 방향의 진폭·진동수·위상차가 평면상의 궤적을 정한다. 같은 진동수에서는 위상차에 따라 직선·타원·원이 나타날 수 있다.',
 '진동수 비가 유리수이면 이상적인 두 진동은 공통 주기 뒤에 같은 상태로 돌아온다. 진동수 비가 무리수이면 정확히 닫힌 궤적이 형성되지 않는다. 평면의 복잡한 궤적과 가로·세로 방향에 투영한 각각의 단순한 운동을 함께 비교하자.');
add('1-2-4-4','리사주 운동의 모의실험',
 '가로와 세로의 진폭, 진동수 비, 위상차를 한 번에 하나씩 바꾸어 궤적을 비교한다. 같은 진동수와 같은 진폭에서 위상차가 0이면 직선 운동, 사분의 일 주기에 해당하면 원운동이 된다. 진폭이 다르면 원 대신 타원이 나타난다.',
 '진동수 비를 1:2, 2:3처럼 바꾸면 여러 고리의 닫힌 곡선이 생긴다. 고리 모양뿐 아니라 한 점의 시간 그래프를 관찰하여 각 방향의 주기를 확인하자. 감쇠가 있으면 같은 위상 관계에서도 궤적의 크기가 점차 작아진다.');
add('1-2-5-1','감쇠력과 감쇠진동',
 '속도와 반대 방향으로 작용하는 저항은 물체의 역학적 에너지를 줄인다. 저항이 속도에 비례하는 모형에서는 진동자의 방정식에 속도 항이 추가된다. 저항이 약하면 진동하면서 진폭이 줄고, 저항이 강하면 왕복하지 않고 평형에 가까워진다.',
 '부족감쇠·임계감쇠·과감쇠는 질량, 용수철 상수, 감쇠 계수의 조합으로 구별된다. 감쇠 계수가 크다고 언제나 평형에 더 빨리 도착하는 것은 아니다. 임계감쇠는 진동 없이 평형으로 돌아오는 경계이며 과감쇠의 느린 성분은 매우 오래 남을 수 있다.');
add('1-2-5-3','감쇠진동 운동분석 모의실험',
 '초기 변위를 주고 놓은 뒤 질점의 위치와 속도를 같은 시각에서 기록하면 감쇠 운동을 정량적으로 분석할 수 있다. 진폭의 포락선, 한 주기의 시간, 역학적 에너지의 감소를 서로 구별하여 측정한다.',
 '질량·용수철 상수·감쇠 계수를 따로 바꾸고 진동하는 경우와 진동하지 않는 경우를 비교하자. 위치가 평형을 통과할 때 속력은 크지만 위치가 극대일 때 속도는 0이다. 아래 HTML 운동 화면과 시간 그래프는 동일한 계산 단계를 사용하여 이 관계를 함께 보여 준다.');
add('1-2-6-1','강제진동',
 '진동자에 주기적인 외력이 작용하면 계의 고유진동과 외력에 의해 유지되는 운동이 함께 나타난다. 처음 상태에 의존하는 과도 성분은 감쇠하고, 충분한 시간이 지나면 구동 주파수와 같은 주파수의 정상상태 진동이 남는다.',
 '정상상태의 진폭과 외력에 대한 위상 지연은 구동 주파수에 따라 달라진다. 감쇠가 작으면 고유진동수 근처에서 큰 응답이 나타난다. 공진점과 진폭은 감쇠의 영향을 받으므로 고유진동수와 최대 진폭의 주파수를 항상 같다고 가정하지 않는다.');
add('1-2-6-2','강제진동의 모의실험',
 '처음에는 정지한 질점에 정현파 외력을 가하면 과도운동과 구동운동이 겹쳐 진폭이 시간에 따라 변한다. 짧은 시간의 최대 변위는 정상상태 진폭과 다를 수 있으므로 충분한 시간을 두고 관찰해야 한다.',
 '구동 주파수를 바꾸어 실제 운동에서 측정한 최대 진폭과 정상상태 이론 곡선을 비교하자. 감쇠가 커지면 과도 성분이 빨리 사라지는 동시에 공진 봉우리도 낮고 넓어진다. HTML 화면에서는 질점 위치·시간 그래프·측정 진폭을 같은 수치 갱신에서 계산한다.');
add('1-2-6-4','공명과 파국',
 '외부 구동이 계의 고유 모드에 계속 에너지를 공급하면 큰 진동이 발생할 수 있다. 구조물의 진동을 평가할 때에는 구동 주파수뿐 아니라 감쇠, 결합, 여러 고유 모드와 외력의 공간 분포를 함께 고려해야 한다.',
 '큰 진폭에서는 재료의 비선형성과 손상이 나타나므로 작은 진동의 선형 공명식만으로 모든 파괴 현상을 설명할 수 없다. 바람에 의한 다리의 불안정성처럼 외부 유동과 구조물의 운동이 서로 영향을 주는 경우에는 자려진동과 공력 불안정성을 구별해야 한다.');
add('2-1-3-2','조화파','조화파는 공간과 시간에 대해 정현함수로 변하는 파동이다. 진폭은 최대 변위, 파장은 같은 위상의 두 점 사이 거리, 주기는 한 위치에서 같은 운동이 반복되는 시간이다. 한 방향의 진행파에서 파장과 진동수의 곱은 위상속도이며, 복잡한 선형 파동도 여러 조화파의 중첩으로 분석할 수 있다.');
add('2-1-3-3','원운동, 진동, 파동의 관계','등속 원운동하는 점을 지름 위에 투영하면 조화진동이 된다. 원의 반지름은 진폭, 회전 각속도는 진동의 각진동수에 대응한다. 공간에 늘어선 점들이 같은 진동수로 진동하되 위치에 따라 위상이 달라지면 진행하는 조화파가 만들어진다. 한 점의 왕복운동과 파형의 이동을 구별하자.');
add('2-1-3-3','파동의 공간측면과 시간측면','한 시각에 줄 전체를 보면 위치에 따른 파형을 얻고, 줄의 한 점을 계속 관찰하면 시간에 따른 진동을 얻는다. 공간 그래프의 반복 간격은 파장이고 시간 그래프의 반복 간격은 주기다. 두 그래프의 가로축 단위가 다르므로 겉모양이 같아도 그대로 겹쳐 비교해서는 안 된다.');
add('2-1-3-4','조화파의 모의실험','횡파에서는 입자의 변위가 진행 방향에 수직이고 종파에서는 나란하다. 공간 파형에서 평형선으로부터 최대 변위를 재어 진폭을, 연속한 마루 사이를 재어 파장을 구한다. 한 입자의 반복 시간을 측정해 주기를 얻은 뒤 파장 나누기 주기가 실제 파형의 이동 속도와 같은지 확인하자.');
add('2-1-3-5','2차원 파동','수면이나 얇은 막의 파동은 두 공간 좌표와 시간에 의존한다. 점에서 발생한 교란은 균일한 매질에서 원형으로 퍼지고, 멀리 떨어진 작은 구역에서는 거의 평면파처럼 보인다. 에너지가 점점 긴 원주에 분산되므로 흡수가 없어도 진폭이 줄 수 있다. 깊은 물과 얕은 물의 수면파는 분산 관계가 다르다.');
add('2-1-3-6','파면','파면은 같은 시각에 같은 위상을 가진 점들을 이은 선 또는 면이다. 2차원에서는 곡선, 3차원에서는 면이 된다. 인접한 파면 사이 거리는 조화파의 파장에 해당한다. 균일하고 등방적인 매질에서는 파면에 수직인 방향이 전파 방향이지만, 이방성 매질에서는 에너지의 진행 방향과 일치하지 않을 수 있다.');
add('2-1-3-7','3차원 파동','소리나 전자기파는 공간의 세 방향으로 퍼질 수 있다. 균일한 공간의 점파원에서는 같은 위상인 점들이 구면을 이룬다. 흡수 없이 일정한 전력이 방출되면 구면의 면적이 거리의 제곱으로 늘어 세기는 거리의 제곱에 반비례한다. 따라서 세기와 파동량의 진폭을 같은 양으로 해석하지 않는다.');
add('2-1-4-1','경계에서의 파동의 반사','줄의 고정단에서는 끝점 변위가 항상 0이어야 한다. 입사 펄스와 반사 펄스가 이 조건을 만족하도록 더해지므로 반사 펄스의 부호가 뒤집힌다. 이상적인 자유단에서는 끝의 기울기가 0인 조건을 만족시키며 반사 변위의 부호가 유지된다. 반사 방향과 변위 방향은 서로 다른 개념이다.');
add('2-1-4-1','반사파의 위상변화','정현파가 고정단에서 반사되면 변위의 부호 반전은 위상차 π로 표현된다. 자유단에서는 변위 반사계수가 양수여서 이런 반전이 없다. 펄스에는 하나의 위상값을 부여하기 어려우므로 위상 변화 대신 파형의 상하 반전을 비교하는 편이 명확하다. 경계에서 합성 변위가 조건을 만족하는지 확인하자.');
add('2-1-4-2','경계에서의 파동의 반사와 투과','서로 다른 줄이 이어진 경계에서는 변위의 연속성과 횡방향 힘의 평형을 동시에 만족해야 한다. 그 결과 입사파의 일부가 반사되고 나머지가 다른 줄로 전달된다. 진동수는 같지만 전파속도가 달라지면 파장도 달라진다. 같은 장력의 줄에서는 선밀도 차이가 속도와 파동 임피던스를 정한다.');
add('2-1-4-2','파동의 반사와 투과 모의실험','입사 펄스가 경계에서 분리되는 동안의 모양만으로 반사 진폭을 판단하기 어렵다. 충분히 분리된 뒤 입사·반사·투과 파형의 높이와 폭을 비교하자. 같은 장력에서 무거운 줄로 들어가는 변위 반사파는 뒤집히고 가벼운 줄로 들어가는 반사파는 뒤집히지 않는다. 에너지 비율에는 진폭뿐 아니라 임피던스도 들어간다.');
add('2-2-1-1','파동의 중첩','선형 파동방정식의 두 해를 더하면 그 합도 해가 된다. 두 펄스가 겹친 위치에서는 순간 변위가 더해지지만, 통과한 뒤에는 각각의 파형이 유지된다. 이 성질은 매질 입자끼리 서로 통과한다는 뜻이 아니다. 큰 진폭의 비선형 파동에서는 단순한 중첩이 성립하지 않을 수 있다.');
add('2-2-1-4','일반적인 맥놀이','가까운 여러 진동수의 진동을 더하면 빠른 진동의 진폭이 느리게 변하는 묶음이 나타난다. 두 진동의 맥놀이 빈도는 진동수 차이이고, 일정한 간격의 여러 성분이 같은 위상으로 더해지면 더 좁은 시간 펄스를 만들 수 있다. 성분 수와 진동수 범위가 시간적 집중 정도에 미치는 영향을 구별하자.');
add('2-2-1-4','정상파와 공명','같은 진동수와 진폭의 파가 반대 방향으로 진행하며 겹치면 위치가 고정된 마디와 배가 생긴다. 경계조건에 맞는 정상파만 유한한 줄에서 고유 모드로 존재할 수 있다. 외력이 이 모드에 반복해서 에너지를 공급하면 공명 응답이 커진다. 정상파의 공간 모양과 구동에 의한 에너지 증가를 구별해야 한다.');
add('2-2-2-1','파동묶음','여러 파수의 파동을 중첩하면 공간의 일부에 집중된 파동묶음을 만들 수 있다. 공간 폭을 줄이려면 더 넓은 파수 범위가 필요하다. 분산이 있는 매질에서는 파수마다 진행 속도가 달라져 묶음이 퍼질 수 있다. 묶음의 포락선 속도인 군속도와 내부 마루의 위상속도는 일반적으로 다르다.');
add('2-2-2-1','파동묶음 모의실험','두 조화파의 파수와 각진동수를 달리하면 빠른 마루와 느린 포락선을 따로 추적할 수 있다. 두 성분이 가까울 때 포락선 속도는 각진동수 차이를 파수 차이로 나눈 값으로 근사된다. 마루가 포락선 안으로 들어왔다가 빠져나갈 수 있으며, 이때 한 마루를 묶음 전체의 위치로 오인하지 않도록 한다.');
add('2-2-3-2','조화파동의 합성 모의실험','서로 다른 각속도로 회전하는 벡터를 더하고 한 축에 투영하면 여러 조화진동이 중첩된 신호가 된다. 회전 반지름은 각 성분의 진폭, 처음 방향은 위상을 나타낸다. 주파수 비가 정수일 때 합성 신호의 공통 주기를 확인하고, 진폭이나 위상을 바꾸어 파형이 어떻게 달라지는지 비교하자.');
add('2-2-3-4','파동의 성분','주기 신호의 푸리에 성분은 기본진동과 그 정수배 진동수의 진폭·위상이다. 사각파나 톱니파를 몇 개 성분만으로 합성하면 세부 모양이 매끄럽게 표현되고, 높은 주파수 성분을 늘리면 급격한 변화가 더 잘 나타난다. 불연속점 부근의 깁스 진동은 항을 늘려도 상대적인 최대 초과량이 완전히 사라지지 않는다.');
add('2-2-3-5','디지털 푸리에 변환','연속 신호를 일정한 시간 간격으로 표본화하면 유한한 수열을 얻는다. 이산 푸리에 변환은 그 수열을 서로 다른 주파수의 복소 성분으로 바꾼다. 주파수 분해능은 관측 시간의 역수이고, 표본화 주파수의 절반보다 높은 성분은 앨리어싱을 일으킬 수 있다. 측정 창과 표본 간격을 함께 확인해야 한다.');
add('2-2-3-5','FFT 해석','FFT는 이산 푸리에 변환과 다른 물리적 변환이 아니라 같은 결과를 빠르게 계산하는 알고리즘 계열이다. 직접 계산의 연산 수는 대략 표본 수의 제곱에 비례하지만 대표적인 FFT는 표본 수 곱하기 로그 표본 수에 비례한다. 계산 속도와 주파수 분해능을 구별하며 영을 덧붙이는 것만으로 실제 정보가 늘지는 않는다.');
add('2-2-4-2','공명','제한된 영역의 파동은 경계조건을 만족하는 고유 모드를 가진다. 외력이 특정 모드의 주파수 가까이에서 그 모드와 잘 겹치는 공간 형태로 작용하면 큰 응답이 생긴다. 실제 공명 진폭은 감쇠와 공급 에너지에 의해 제한된다. 외력 주파수가 같아도 마디에 힘을 가하면 그 모드를 잘 자극하지 못할 수 있다.');
add('2-2-4-2','줄의 공명','길이 L인 균일한 줄의 양끝을 고정하면 양끝이 변위 마디가 되어야 한다. 허용 파장은 2L을 양의 정수로 나눈 값이고 고유진동수는 기본진동수의 정수배다. 장력을 올리면 파속과 고유진동수가 커지며, 선밀도를 높이면 작아진다. 모드 번호가 늘어날수록 줄 안의 마디 수도 증가한다.');
add('2-2-4-2','자유단이 있는 줄의 공명','한 끝은 변위가 0인 고정단, 다른 끝은 기울기가 0인 이상적인 자유단이라면 양끝에는 각각 마디와 배가 놓인다. 줄 길이에는 사분의 일 파장의 홀수배가 들어가므로 고유진동수도 기본진동수의 홀수배가 된다. 실제 자유단을 만드는 지지 구조가 추가 질량이나 마찰을 주면 이상 모형과 차이가 난다.');
add('2-2-4-2','공명의 양상','1차원의 정상파 마디는 점이지만 2차원 막에서는 마디선, 3차원 공동에서는 마디면을 이룬다. 모드의 모양과 고유진동수는 영역의 형태와 경계조건에 의해 결정된다. 같은 주파수의 서로 다른 모드가 존재하면 상대 진폭과 위상에 따라 여러 마디 무늬를 만들 수 있다.');
add('2-2-4-3','관의 공명','공기가 진동하는 관의 막힌 끝에서는 입자 변위가 마디이고 압력 변화가 배다. 열린 끝에서는 압력 변화가 거의 마디이고 변위가 배가 된다. 양끝이 열린 관과 한쪽만 열린 관은 서로 다른 고유진동수 배열을 가진다. 열린 끝의 보정 때문에 실제 유효 길이는 관의 기하학적 길이보다 조금 길다.');
add('2-2-4-4','원형 막의 정상파','테두리가 고정된 원형 막에서는 반지름 방향의 베셀 함수와 각도 방향의 정현함수를 결합해 정상 모드를 표현한다. 마디에는 동심원과 지름 방향 선이 나타날 수 있다. 고유진동수는 일반적으로 기본진동수의 정수배가 아니므로 줄의 배음과 다른 음색을 만든다. 막의 장력과 면밀도도 진동수를 결정한다.');
add('2-2-4-6','중첩된 직사각형 정상상태 모의실험','직사각형 막의 모드는 두 방향의 마디 수로 구별한다. 두 모드를 더하면 각각의 진폭과 상대 위상에 따라 순간적인 모양과 마디 분포가 달라진다. 가로세로 길이의 비를 바꾸면 두 고유진동수도 변하므로 같은 모드 번호라도 시간 운동이 달라진다. 같은 주파수의 모드와 다른 주파수의 모드를 구별하자.');
add('2-2-5-1','파동의 간섭','같은 지점에 도달한 파동은 위상차에 따라 합성 진폭이 커지거나 작아진다. 일정한 간섭무늬를 관찰하려면 상대 위상이 측정 시간 동안 안정해야 한다. 같은 진폭의 두 파에서 위상차가 0이면 최대 보강, π이면 완전 상쇄가 된다. 세기는 진폭의 제곱에 비례하므로 개별 세기만 단순히 더할 수 없다.');
add('2-2-5-1','수면파의 간섭','같은 진동수의 두 점파원이 수면에 파를 보내면 경로차가 일정한 곡선을 따라 보강과 상쇄 무늬가 생긴다. 파원이 같은 위상일 때 경로차가 파장의 정수배이면 보강되고 반정수배이면 상쇄된다. 수면의 높이가 순간적으로 0인 곳과 진폭이 계속 0인 마디를 구별해야 한다.');
add('2-2-5-2','물결통 실험의 모의실험','두 파원의 간격을 늘리거나 파장을 줄이면 원거리 간섭무늬의 각도 간격이 좁아진다. 상대 위상을 바꾸면 마디선과 보강선의 위치가 움직인다. 고정된 관찰점의 시간 진동과 물결통 전체의 순간 높이를 함께 비교해, 파형의 이동 속에서도 간섭 진폭의 공간 분포가 유지되는 조건을 살펴보자.');
add('2-2-5-4','음파의 간섭','위상이 안정된 두 스피커가 같은 진동수의 소리를 내면 위치에 따라 압력 진폭이 달라진다. 귀나 마이크를 옮기면 큰 소리와 작은 소리가 반복되는 구역을 찾을 수 있다. 소리가 작아진 곳의 에너지가 사라지는 것이 아니라 다른 방향으로 재분배된다. 실내 반사음은 단순한 두 파원 무늬를 바꾼다.');
add('2-2-5-4','음파의 간섭 실험','같은 신호를 두 스피커에 공급하고 스피커 간격·진동수·상대 위상을 따로 바꾸어 마이크의 신호를 비교한다. 파장을 음속과 진동수로 구한 뒤 예상 경로차 조건과 측정된 최소·최대 위치를 대조하자. 두 스피커가 서로 다른 진동수이면 고정된 간섭무늬 대신 시간에 따라 변하는 맥놀이가 나타난다.');
add('2-2-6-1','무아레 무늬','촘촘한 두 격자가 약간 다른 간격이나 방향으로 겹치면 훨씬 넓은 간격의 무아레 무늬가 보인다. 각 격자의 공간 주파수 차이가 느린 무늬를 만든다는 점에서 맥놀이와 비슷하다. 실제 파동의 에너지가 간섭한 것은 아니므로 밝고 어두운 격자 중첩과 물리적인 파동 간섭을 구별한다.');
add('2-2-6-1','여러 가지 무아레 무늬','평행선 두 장은 띠 무늬를, 중심이 다른 동심원 두 장은 휘어진 무늬를 만든다. 정사각 격자와 원형 격자처럼 형태가 다르면 위치에 따라 무늬 간격과 방향도 달라진다. 격자를 조금 회전하거나 이동했을 때 큰 무늬가 어떻게 변하는지 관찰하면 원래의 작은 변형을 확대해서 볼 수 있다.');
add('2-2-6-2','무아레 무늬의 활용','격자 간격이 비슷할수록 무아레 무늬의 간격은 커지고 작은 상대 변위가 큰 무늬 이동으로 나타난다. 이 확대 효과는 미세 변위·회전·표면 변형을 측정하는 데 이용된다. 무늬의 이동 방향과 실제 격자의 이동 방향이 다를 수 있으므로 격자 간격과 회전각을 알고 해석해야 한다.');
add('2-2-6-3','두 파동의 간섭','두 파원의 파면을 일정한 간격의 선으로 그려 겹치면 경로차가 같은 곳에 무아레 무늬가 형성된다. 동심원은 점파원, 평행선은 평면파의 위상을 나타내는 기하학적 모형이다. 이런 그림은 간섭 위치를 이해하는 데 유용하지만 실제 진폭의 합이나 세기를 정량적으로 얻으려면 파동함수를 계산해야 한다.');
add('2-2-6-4','무아레 무늬를 이용한 여러 구면파의 간섭','세 개 이상의 파원을 배열하면 모든 파원의 위상과 경로를 함께 더해야 하므로 두 파원보다 복잡한 무늬가 나타난다. 일정 간격의 배열에서는 특정 방향의 보강이 뚜렷해질 수 있다. 동심원 격자 그림에서 주된 보강 방향을 찾고, 파원 수를 늘리면 그 방향의 무늬가 얼마나 좁아지는지 비교하자.');
add('2-2-7-1','호이헨스 원리','현재 파면의 각 점을 작은 이차 파원의 위치로 보고, 일정 시간 뒤 그 파들이 이루는 포락선으로 다음 파면을 구성할 수 있다. 이 방법은 반사·굴절의 기하학적 관계를 설명한다. 회절 세기를 계산하려면 이차 파동들의 위상과 진폭을 더하는 호이헨스–프레넬 관점이 필요하다.');
add('2-2-7-4','틈에서의 회절','좁은 틈을 지난 파동은 기하학적인 그림자 영역까지 퍼진다. 틈의 폭이 파장과 비슷할수록 퍼짐이 뚜렷하고, 먼 거리에서는 틈 안의 각 위치에서 나온 파의 위상차가 회절 분포를 결정한다. 관찰점이 가까우면 거리 차이를 더 정확히 포함하는 프레넬 회절을 사용해야 한다.');
add('2-3-1-1','음파','공기 중의 소리는 압력과 밀도의 작은 변화가 전파되는 종파다. 분자의 빠른 열운동 위에 작은 집단적 진동이 겹치지만 공기 전체가 음원에서 귀까지 이동하는 것은 아니다. 진동수는 주로 음높이, 압력 진폭은 소리의 세기와 관련되며 파형의 여러 주파수 성분은 음색을 정한다.');
add('2-3-1-2','진동의 양상','종파에서는 공기 입자의 변위, 밀도 변화, 압력 변화를 각각 그릴 수 있다. 입자들이 가장 빽빽한 곳은 압력 변화가 최대인 곳이며, 조화파에서 입자 변위와 압력 변화는 공간적으로 사분의 일 파장만큼 어긋난다. 세로축을 압력으로 그린 정현파 그림을 실제 공기의 횡방향 흔들림으로 해석하면 안 된다.');
add('2-3-2-1','도플러 효과','음원과 관찰자가 매질에 대해 움직이면 관측되는 진동수가 방출 진동수와 달라진다. 음원이 다가오면 앞쪽 파면 간격이 좁아지고 관찰자가 음원 쪽으로 움직이면 단위 시간에 더 많은 파면을 만난다. 소리에서는 두 운동의 효과가 매질 기준으로 구별되며 빛의 상대론적 도플러식과 혼용하지 않는다.');
add('2-3-2-1','충격파','파원이 파동의 전파속도보다 빠르면 앞서 방출한 파면들의 포락선이 뒤쪽 원뿔을 이룬다. 초음속 운동에서 나타나는 마하 원뿔의 반각은 음속과 파원 속도의 비로 정해진다. 실제 충격파는 압력과 밀도가 급격히 변하는 비선형 현상이며, 선형 파면 그림의 겹침이 실제 무한 진폭을 뜻하지는 않는다.');
add('2-3-2-3','도플러 효과에 대한 모의실험 1','음원과 관찰자의 속도와 위치를 독립적으로 정해 만나는 파면 수를 비교한다. 접근할 때와 멀어질 때의 진동수를 기록하고, 관찰자가 음원을 지나기 전후에 달라지는 방사 방향도 살펴보자. 아음속 도플러식은 분모가 0이 되는 음속 부근이나 초음속 충격파에 그대로 적용할 수 없다.');
add('2-3-2-4','도플러 효과에 대한 모의실험 2','직선 운동과 원운동하는 파원의 파면을 비교하면 관찰 방향에 따른 진동수 변화를 이해할 수 있다. 각 파면의 중심은 파가 방출된 순간의 음원 위치에 남고 반지름만 음속으로 커진다. 원운동에서는 관찰자 쪽 속도 성분이 계속 변하므로 같은 속력으로 움직여도 관측 진동수가 주기적으로 바뀔 수 있다.');
add('2-3-3-1','악기','악기는 줄·공기 기둥·막 등의 진동을 공기에 전달하여 소리를 낸다. 경계조건과 재료가 고유진동수를 정하고, 연주 방식이 각 모드의 진폭과 시간 변화를 정한다. 같은 기본음이라도 배음의 상대 세기와 소리가 시작하고 사라지는 모양이 달라 음색이 달라진다. 공명통은 진동을 공기에 전달하는 효율에도 영향을 준다.');
add('2-3-3-1','현악기','양끝이 고정된 현에서는 유효 길이·장력·선밀도가 기본진동수를 결정한다. 줄을 누르면 진동하는 길이가 줄어 음높이가 올라가고, 장력을 높여도 음이 높아진다. 줄을 뜯거나 활로 마찰시키는 위치와 방법은 여러 모드의 상대 진폭을 달리한다. 줄 자체의 작은 진동은 몸통과 공명통을 통해 소리로 전달된다.');
add('2-3-3-2','관악기','관악기의 음은 관 내부 공기의 정상파와 입구의 구동이 결합하여 만들어진다. 열린 구멍은 유효 길이와 경계조건을 바꾸며, 리드와 입술은 자려진동으로 에너지를 공급한다. 열린 관과 한쪽이 막힌 관의 이상 모드는 배음 배열이 다르지만 실제 악기는 관의 형상과 끝 보정 때문에 단순한 관 모형과 차이가 난다.');
add('2-3-3-3','타악기','북의 막이나 금속판은 2차원 진동 모드를 가진다. 때리는 위치에 따라 어떤 모드가 강하게 생기는지가 달라지고, 막의 장력이나 재료는 진동수를 바꾼다. 많은 타악기의 고유진동수는 정수배 배음 배열을 이루지 않는다. 북통 내부의 공기 진동과 막의 진동이 결합하므로 막만의 진동으로 전체 음색을 설명할 수는 없다.');
add('2-3-3-4','신시사이저','신시사이저는 전기 신호나 디지털 계산으로 소리 파형을 만든다. 여러 정현파를 더하는 가산 합성, 풍부한 파형을 필터로 가공하는 감산 합성, 실제 음원의 표본을 사용하는 방식 등이 있다. 주파수 성분뿐 아니라 시간에 따른 진폭 포락선과 변조를 조절하면 기존 악기의 음색이나 새로운 소리를 만들 수 있다.');
add('2-3-3-4','미디','MIDI는 소리 파형 자체가 아니라 음의 시작·종료, 음높이, 세기, 악기 선택 등을 전달하는 연주 제어 규약이다. 같은 MIDI 데이터도 연결된 음원에 따라 다른 소리로 재생될 수 있다. 녹음된 오디오와 연주 지시 데이터를 구별하고, 여러 악기 파트가 동시에 진행되는 시간 순서를 살펴보자.');
add('3-1-1-3','보일-샤를의 법칙 모의실험2','용기 속 입자들이 벽에 전달하는 운동량을 시간 평균하면 압력을 구할 수 있다. 같은 온도에서 용기 면적이나 부피를 줄이면 벽과의 충돌이 잦아져 압력이 커진다. 피스톤의 움직임과 입자 속도 분포를 함께 관찰하되, 2차원 모형의 면적·압력 정의를 실제 3차원의 부피와 그대로 동일시하지 않는다.');
add('3-1-1-4','보일-샤를의 법칙 모의실험3','3차원 용기에 입자를 넣으면 모든 방향의 속도 성분이 벽과의 충돌에 기여한다. 일정한 입자 수에서 압력·부피·온도를 비교하여 이상기체 상태방정식의 관계를 확인한다. 압력을 구할 때에는 한 번의 충돌력이 아니라 충분한 시간 동안 벽이 받은 충격량을 벽면 넓이와 측정 시간으로 나누어야 한다.');
add('3-1-2-1','이상기체','이상기체는 입자의 크기와 입자 사이의 장거리 상호작용을 무시하는 모형이다. 벽에 부딪히는 입자의 운동량 변화가 압력을 만들며 평균 병진 운동에너지는 절대온도에 비례한다. 밀도가 낮고 응축에서 먼 실제 기체는 이 모형에 가까워질 수 있다. 높은 밀도나 낮은 온도에서는 상호작용과 양자 효과를 확인해야 한다.');
add('3-1-2-2','기체의 속도분포','평형 기체의 분자는 모두 같은 속력으로 움직이지 않는다. 탄성충돌로 에너지를 주고받은 많은 입자는 맥스웰 속도분포를 형성한다. 온도가 높을수록 분포는 더 큰 속력 쪽으로 넓어지고, 같은 온도에서는 가벼운 분자의 전형적 속력이 더 크다. 평균속력·최빈속력·제곱평균제곱근속력은 서로 다르다.');
add('3-1-2-3','통계역학','통계역학은 모든 입자의 궤적을 추적하는 대신 가능한 미시상태의 확률로 거시적 물리량을 계산한다. 같은 에너지와 입자 수라도 매우 많은 미시상태가 대응할 수 있다. 평형에서의 평균과 요동을 구별하고, 에너지·입자 교환 조건에 따라 미시정준·정준·거대정준 집합을 선택한다.');
add('3-1-2-4','이상기체의 통계역학적 해석','온도가 정해진 열저장체와 에너지를 교환하는 계에서 각 미시상태의 가중치는 볼츠만 인자에 비례한다. 기체의 위치와 운동량을 합쳐 위상공간을 구성하고 가능한 상태들을 합하면 분배함수를 얻는다. 확률을 정규화한 뒤 평균 에너지와 압력을 계산할 수 있으며, 에너지 구간의 확률에는 그 구간의 상태 수가 함께 들어간다.');
add('3-1-3-1','에너지 등분배의 모의실험','고전적인 열평형에서 에너지의 독립적인 이차항 하나당 평균 에너지는 kBT/2다. 따라서 질량이 다른 입자도 같은 병진 자유도에서 평균 에너지가 같지만 평균 속력은 다르다. 순간 에너지가 같다는 뜻은 아니므로 충분한 시간 평균을 비교하자. 낮은 온도에서 양자화된 자유도는 등분배를 따르지 않을 수 있다.');
add('3-1-4-1','수송현상','농도·온도·속도의 공간 차이가 있으면 입자의 무작위 운동과 충돌을 통해 물질·열·운동량이 전달된다. 각각 확산·열전도·점성으로 나타나며, 평형에서 벗어난 작은 구배에서는 흐름이 구배에 비례하는 모형을 쓴다. 평균 자유행로와 충돌 시간은 미시 운동과 거시 수송계수를 연결한다.');
add('3-1-4-1','확산','개별 입자가 무작위로 움직여도 입자가 많은 쪽에서 적은 쪽으로 더 많이 넘어가므로 순 흐름이 생긴다. 단순 확산의 평균제곱변위는 시간에 비례하고 전형적인 퍼짐 길이는 시간의 제곱근으로 증가한다. 평균 위치가 그대로인 대칭적인 퍼짐과 유체 전체가 이동하는 흐름을 구별해야 한다. 식에서 D는 확산계수, d는 공간 차원, c는 농도다.');
add('3-1-4-2','브라운 운동','유체 속의 작은 입자는 주변 분자의 불균형한 충돌을 받아 불규칙하게 움직인다. 관측되는 큰 입자의 느린 운동을 통해 보이지 않는 분자의 열운동을 추론할 수 있다. 입자 크기·온도·유체의 점성이 확산 정도를 결정한다. 짧은 시간의 관성과 긴 시간의 확산 영역을 구별하고 한 궤적보다 여러 궤적의 통계를 비교하자.');
add('3-2-1-1','실제 기체','실제 분자는 유한한 크기를 가지며 서로 끌어당기거나 밀어낸다. 분자의 배제 부피와 인력을 포함한 판데르발스 모형은 이상기체에서 벗어나는 경향과 기체–액체 전이를 설명한다. 그러나 모든 실제 물질의 상태방정식을 정확히 재현하는 것은 아니다. 임계점 부근에서는 큰 밀도 요동도 중요해진다.');
add('3-2-2-1','물질의 상태변화','열운동이 분자 사이의 결합을 얼마나 흔드는지에 따라 기체·액체·고체의 구조가 달라진다. 상태변화에서는 온도뿐 아니라 압력도 중요하다. 일차 상전이의 공존 구간에서 공급한 열은 온도 상승보다 상의 비율 변화에 쓰일 수 있다. 잠열과 한 상 안에서 온도를 높이는 비열을 구별하자.');
add('3-2-2-1','상도표','상도표는 온도와 압력 등의 조건에 따라 안정한 상과 공존 경계를 표시한다. 기체와 액체가 공존하는 동안 전체 부피 변화는 두 상의 비율을 바꿀 수 있다. 판데르발스 등온선의 불안정 구간은 그대로 평형 상태로 사용하지 않고 공존 조건으로 대체한다. 임계점 위에서는 기체와 액체 사이의 뚜렷한 경계가 사라진다.');
add('3-2-2-3','혼합물질의 모의실험','서로 다른 두 종류의 입자를 섞으면 각 종류의 인력과 두 종류 사이의 상호작용이 혼합과 응축을 결정한다. 온도를 낮출 때 어느 성분이 먼저 모이는지 관찰하고 입자 색만으로 결합 세기를 추정하지 않는다. 실제 혼합물의 상분리는 에너지 감소와 섞임의 엔트로피 사이의 경쟁으로 정해진다.');
add('3-2-3-1','액체','액체는 가까이 모인 분자들이 계속 이웃을 바꾸며 움직이는 상태다. 부피는 비교적 일정하지만 고체처럼 고정된 형태를 유지하지 않는다. 작은 압력 변화에 대한 압축률은 기체보다 작고, 흐름에서는 점성이 중요하다. 분자가 정지해 있는 상태로 액체를 해석하지 않도록 한다.');
add('3-2-3-1','액체의 형성','분자 사이 인력이 열운동과 경쟁하면 입자가 응축하여 고밀도 영역을 형성할 수 있다. 액체 내부의 분자는 사방의 이웃과 상호작용하지만 표면의 분자는 비대칭적인 환경에 놓인다. 용기와의 상호작용, 온도, 입자 수를 바꾸어 덩어리의 모양과 표면을 비교하되 작은 입자 모형의 요동을 거시적인 액체와 구별하자.');
add('3-2-3-1','증발','액체 표면의 일부 분자는 충분한 에너지를 얻으면 밖으로 빠져나간다. 반대로 기체 분자가 표면에 들어오면 응축할 수 있다. 밀폐된 용기에서는 두 과정이 균형을 이뤄 증기압이 정해진다. 열린 용기에서 고에너지 분자가 빠져나가면 남은 액체가 냉각될 수 있으며, 증발은 끓는점 아래에서도 일어난다.');
add('3-2-3-2','표면장력','액체의 표면을 늘리는 데에는 자유에너지가 필요하다. 표면장력은 표면적 증가에 대한 에너지 비용이자 경계선 단위 길이에 작용하는 힘으로 해석할 수 있다. 작은 방울은 표면적을 줄이기 위해 둥글어지지만 큰 방울에서는 중력도 모양을 정한다. 비눗막의 앞뒤 두 표면과 액체의 한 표면을 구별해야 한다.');
add('3-2-3-2','모세관 현상','좁은 관에서는 액체의 표면장력과 벽에 대한 젖음성이 중력과 균형을 이루어 액면 높이가 바뀐다. 벽을 잘 적시는 액체는 오목한 메니스커스를 만들며 올라갈 수 있고, 잘 적시지 않는 액체는 내려갈 수 있다. 상승 높이는 관 반지름이 작을수록 커지며 접촉각과 액체 밀도에도 의존한다.');
add('3-3-2-1','비가역반응','기체가 진공 쪽으로 자유 팽창하면 다시 한쪽으로 모이는 역과정은 거시적으로 관찰하기 어렵다. 이상기체의 자유 팽창에서는 열과 일이 없어 에너지가 유지되어도 접근 가능한 상태 수와 엔트로피는 증가한다. 미시 운동법칙의 시간반전 성질과 거시 과정의 비가역성은 서로 다른 수준의 설명이다.');
add('4-1-1-1','전하','전하는 전자기적 상호작용의 원천이며 양과 음의 두 부호를 가진다. 같은 부호끼리는 밀어내고 다른 부호끼리는 끌어당긴다. 전하량과 질량은 서로 다른 물리량이며 중성 물체도 양·음 전하를 내부에 포함할 수 있다. 대전 여부는 한 종류의 전하 존재 자체가 아니라 두 부호의 전체 합으로 판단한다.');
add('4-1-1-1','전하의 양자화','일상적인 고립 물체의 전하량 변화는 기본전하의 정수배로 나타난다. 전자는 음의 기본전하, 양성자는 양의 기본전하를 가진다. 쿼크에는 분수 전하가 있지만 보통 자유로운 고립 입자로 관측되지 않는다. 거시적 물체에는 매우 많은 전자가 있어 전하량이 연속처럼 보이더라도 미시적인 양자화와 모순되지 않는다.');
add('4-1-1-1','전하량보존법칙','닫힌 계의 총전하량은 물리 과정 전후에 유지된다. 마찰 대전은 전하를 새로 만드는 것이 아니라 물체 사이에서 전자를 옮긴다. 입자가 생성되거나 소멸하는 과정에서도 전체 전하 합을 비교해야 한다. 한 부분의 전하가 변했다면 경계를 통과한 전류와 함께 확인한다.');
add('4-1-1-2','도체와 부도체','도체에는 물질 내부를 이동할 수 있는 전하 운반자가 있어 외부 전기장에 전하가 재배치된다. 부도체에서는 전하 이동이 제한되지만 결합된 전하의 작은 이동이나 분자 방향 정렬로 분극이 가능하다. 정전기 평형의 이상 도체 내부 전기장은 0이고 잉여 전하는 표면에 놓인다.');
add('4-1-1-2','검전기','검전기의 두 도체 잎에 같은 부호의 전하가 모이면 서로 밀어내어 벌어진다. 대전 물체를 가까이 가져오는 것만으로도 전하 분리가 생기므로 잎이 벌어졌다고 총전하가 반드시 유입된 것은 아니다. 접촉·비접촉·접지를 구별하고 물체를 멀리했을 때 잎이 다시 닫히는지 비교하자.');
add('4-1-1-2','대전','중성 물체가 전자를 잃거나 얻어 전체 전하 합이 0이 아니게 되는 것을 대전이라 한다. 접촉과 마찰은 전자를 옮기고, 정전기 유도에서는 외부 물체의 전기장이 전하를 재배치한다. 유도로 영구 대전시키려면 접지와 외부 물체를 제거하는 순서가 중요하며 물체와 주변을 포함한 전하는 보존된다.');
add('4-1-1-2','분극','분극은 전체 전하가 0인 물질에서도 양·음 전하의 중심이 어긋나거나 전기쌍극자의 방향이 정렬되는 현상이다. 따라서 분극과 순전하를 공급하는 대전은 다르다. 분극된 중성 물체는 비균일한 전기장에서 힘을 받을 수 있어 대전 물체가 작은 종잇조각을 끌어당기는 현상을 설명한다.');
add('4-1-2-1','전기력','정지한 두 점전하 사이 힘은 전하량의 곱에 비례하고 거리의 제곱에 반비례한다. 방향은 두 전하를 잇는 직선이며 부호에 따라 인력과 척력이 정해진다. 여러 전하가 있으면 각 힘을 벡터로 더한다. 거리만 반으로 줄이면 힘의 크기가 네 배가 되는지 확인하되 물체가 점전하로 근사되는 조건을 살펴보자.');
add('4-2-1-1','전기력선','전기력선의 접선은 그 위치의 전기장 방향을 나타내며, 촘촘한 정도는 전기장 세기를 표현한다. 양전하에서 나와 음전하로 들어가고 한 점에서 두 방향이 될 수 없으므로 교차하지 않는다. 힘선은 실제 물질이나 입자의 궤적이 아니라 벡터장을 시각화한 선이다.');
add('4-2-3-1','가우스 법칙을 이용한 전기장의 계산','닫힌 면을 통과하는 전기선속은 그 안의 총전하량을 진공 유전율로 나눈 값이다. 구·원통·평면 대칭이 충분하면 적분면 위의 전기장을 단순화하여 쉽게 계산할 수 있다. 가우스 법칙은 대칭이 없어도 성립하지만 그때는 총선속 하나만으로 모든 위치의 전기장을 결정하지 못한다.');
add('4-2-3-1','구 바깥의 구면','중심이 같은 대전 구와 반대 전하의 구껍질을 생각하자. 대칭적인 분포에서는 구와 껍질 사이의 전기장이 안쪽 구의 전하로 정해진다. 두 물체의 전하 합이 0이면 바깥의 전기장은 0이다. 껍질이 도체라면 도체 내부의 평형 조건과 안팎 표면의 전하 분포도 함께 만족해야 한다.');
add('4-3-1-2','등전위','등전위선이나 등전위면의 모든 점은 같은 전위를 가진다. 정전기장에서 그 면을 따라 시험전하를 옮기면 전기력이 한 일은 0이며 전기장은 등전위면에 수직이다. 전위의 절대 기준은 선택할 수 있지만 전위차와 전기장은 그 선택과 무관하다. 선 간격이 좁을수록 전위의 공간 변화가 커진다.');
add('4-3-1-2','번개','구름 내부의 전하 분리가 커지면 공기의 절연 상태가 깨지고 전하가 방전된다. 방전 통로의 공기는 급격히 가열되어 빛과 압력파를 낸다. 빛이 소리보다 훨씬 빨리 도달하므로 번개 뒤에 천둥이 들린다. 단순한 두 전극의 정전기 모형은 개념을 설명하지만 실제 방전의 가지 구조와 시간 변화를 모두 설명하지는 않는다.');
add('4-3-2-3','라플라스 방정식의 수치해석 2','전하가 없는 정사각형 내부에서 경계 전위를 지정하면 내부 전위는 라플라스 방정식을 만족한다. 균일 격자에서는 각 내부 값을 이웃 네 점의 평균으로 반복 갱신하는 이완법을 쓸 수 있다. 전극 값은 고정하고 내부 잔차가 충분히 작아지는지 확인해야 하며 반복 횟수만으로 정확도를 판단하지 않는다.');
add('4-3-2-5','3차원 라플라스 방정식의 수치해석','3차원 균일 격자의 전하 없는 내부에서는 여섯 이웃의 평균으로 전위를 갱신할 수 있다. 정육면체의 두 면에 전압을 걸고 나머지 면을 접지하면 옆면 때문에 무한 평행판과 다른 전위 분포가 생긴다. 단면과 등전위면을 함께 비교하고 경계 근처의 급한 변화를 더 작은 격자로 검증하자.');
add('4-3-2-5','3차원 라플라스 방정식의 수치해석 2','접지된 직육면체 안에 서로 다른 전위의 내부 전극을 놓으면 벽과 전극을 모두 고정 경계로 다루어야 한다. 내부 전극 사이 전기장은 전위의 공간 기울기로 구한다. 등전위면의 모양을 바꾸는 요인이 전극의 위치인지 용기의 비율인지 따로 비교하고, 격자 간격을 줄여 결과가 안정되는지 확인하자.');
add('4-3-3-1','축전기의 병렬연결과 직렬연결','병렬로 연결한 축전기는 같은 전위차를 가지며 각 전하량이 더해져 정전용량도 더해진다. 직렬에서는 중간 연결부의 순전하가 처음 0인 조건에서 각 축전기에 같은 크기의 전하가 저장되고 전위차가 나뉜다. 직렬 합성 정전용량의 역수는 각 역수의 합이다. 연결 방식에 따라 에너지와 전압 분배도 달라진다.');
add('4-4-2-2','옴의 법칙 모의실험','장애물 사이를 굴러가는 구슬은 전기장에 의해 가속하다 산란되는 전하의 표류를 비유한다. 구슬의 순간 속도와 평균 이동 속도를 구별하고 경사가 커질 때 평균 흐름이 어떻게 변하는지 비교한다. 실제 전자의 무작위 열운동과 양자 성질까지 구슬 모형으로 설명할 수는 없지만 산란이 흐름을 제한하는 원리를 이해할 수 있다.');
add('4-4-2-3','옴의 법칙 모의실험2','전하 운반자는 전기장에서 가속하고 격자와 불순물 등에 산란되며 평균적으로 일정한 표류 속도를 형성한다. 작은 장에서 평균 산란 시간이 일정하면 전류가 전기장에 비례한다. 운반자 수와 산란 장애물을 따로 바꾸어 전도도의 변화를 비교하자. 큰 장이나 온도 변화가 있으면 저항이 일정하다는 가정이 깨질 수 있다.');
add('4-5-1-1','플레밍의 왼손법칙','자기장 속의 전류가 흐르는 도선은 전류 방향과 자기장 방향에 모두 수직인 힘을 받는다. 왼손의 중지·검지·엄지를 각각 관습적인 전류·자기장·힘 방향에 맞추면 방향을 기억할 수 있다. 실제 계산은 벡터곱으로 확인하며 전자의 이동 방향은 관습적 전류 방향과 반대임에 유의한다.');
add('4-5-1-1','전동기','자기장 속 코일의 마주 보는 두 변이 반대 방향 힘을 받아 회전 토크를 만든다. 직류 전동기의 정류자는 반 바퀴마다 코일 전류를 바꾸어 토크 방향을 유지한다. 회전할 때 생기는 역기전력도 전류를 제한한다. 전기 에너지가 역학적 일로 바뀌는 과정과 저항에서 발생하는 열을 구별하자.');
add('4-5-1-3','영구자석','영구자석은 원자 수준의 자기모멘트와 자기구역이 정렬되어 외부 자기장을 유지한다. 막대자석을 나누어도 각각의 조각에 두 극이 생기며 전하처럼 고립된 한 극만 남지는 않는다. 재료와 온도에 따라 자화가 유지되는 정도가 달라지고, 외부 자기장에 의해 자기구역의 배열을 바꿀 수 있다.');
add('4-5-1-3','지구 자기장','지구의 자기장은 주로 외핵의 전도성 유체 운동에 의해 유지된다. 나침반은 국소 자기장의 수평 성분에 정렬되며 지리적 북쪽과 정확히 같은 방향을 항상 가리키지는 않는다. 지표의 자기장은 경사각과 편각을 가지며 단순한 중심 쌍극자 모형에서 벗어난 성분도 있다.');
add('4-6-1-1','발전기','자기장 속에서 코일을 회전시키면 코일을 통과하는 자기선속이 변하여 기전력이 생긴다. 일정한 각속도로 회전하는 이상 코일에서는 선속과 기전력이 정현파로 변한다. 전류가 흐를 때 회전을 방해하는 토크가 생기므로 외부에서 역학적 일을 계속 공급해야 한다. 발전은 에너지를 새로 만드는 과정이 아니다.');
add('4-6-1-2','유도전류의 발생 모의실험','자석을 코일에 가까이하거나 멀리하면 선속 변화에 따라 유도기전력의 부호가 달라진다. 같은 위치에서도 자석을 빨리 움직이면 더 큰 기전력이 생길 수 있고 정지시키면 일정한 자석의 선속만으로는 전류가 계속 유도되지 않는다. 선속·기전력·전류의 시간 그래프를 구별하고 회로 저항과 인덕턴스도 고려한다.');
add('4-6-1-2','렌츠의 법칙','유도전류는 자기선속의 변화를 방해하는 방향의 자기장을 만든다. 증가하는 선속을 줄이거나 감소하는 선속을 보충하는 방향이지 언제나 원래 자기장과 반대라는 뜻은 아니다. 면의 법선과 양의 순환 방향을 먼저 정한 뒤 패러데이 법칙의 음의 부호를 해석하면 방향 혼동을 줄일 수 있다.');
add('4-7-2-1','인공 전자기파의 발생','시간에 따라 가속하는 전하는 전자기 복사를 만들 수 있다. 진동 회로와 안테나는 전류와 전기장의 변화를 공간으로 전달하며 수신 안테나에서는 그 장이 전하를 움직인다. 헤르츠의 실험은 전기 진동으로 생성한 파동의 반사·편광 등을 통해 빛과 같은 전자기적 성질을 확인했다.');
add('4-7-2-3','전자기파 스펙트럼','전파·마이크로파·적외선·가시광선·자외선·엑스선·감마선은 모두 전자기파이며 주파수와 발생 방식으로 구별한다. 진공에서는 같은 속도로 진행하고 파장은 주파수에 반비례한다. 광자 에너지는 주파수에 비례하므로 같은 세기라도 물질과의 상호작용은 다르다. 각 영역의 경계는 관용적인 분류다.');
add('5-1-1-2','굴절법칙의 작도법','경계 법선에 대한 입사각과 굴절각은 스넬의 법칙으로 연결된다. 두 매질의 굴절률에 비례하는 원을 같은 중심에 그리고 접선 방향 성분을 비교하면 굴절 방향을 작도할 수 있다. 각도를 경계면 자체에서 재지 않도록 주의한다. 굴절률이 큰 쪽으로 들어가면 보통 법선 쪽으로 꺾인다.');
add('5-1-1-3','굴절에 대한 모의실험','파면의 한쪽이 경계를 먼저 통과하면 두 매질에서의 전파속도 차이 때문에 파면이 회전한다. 입사각과 굴절률 비를 따로 바꾸어 광선과 파면을 비교하자. 높은 굴절률에서 낮은 굴절률로 진행할 때 임계각을 넘으면 전파하는 굴절 광선이 사라지고 전반사가 나타난다.');
add('5-1-2-1','광선','광선은 빛의 에너지 흐름과 진행 방향을 나타내는 기하학적 선이다. 균일하고 등방적인 매질에서는 파면에 수직이다. 빛의 파장보다 큰 구조를 다룰 때 유용하지만 좁은 틈의 회절이나 간섭무늬는 광선만으로 설명할 수 없다. 선의 개수 자체를 빛의 세기로 해석하려면 별도의 가중치가 필요하다.');
add('5-1-2-1','광선의 행동','굴절률이 일정한 영역에서 광선은 직진하고 경계에서는 반사와 굴절로 갈라질 수 있다. 경계 법선과의 각도로 반사·굴절 법칙을 적용하고, 각 경로의 빛의 양은 프레넬 계수로 구한다. 굴절률이 공간에 따라 연속적으로 달라지면 경로도 연속적으로 휘므로 여러 직선 조각의 추적으로 근사할 수 있다.');
add('5-1-2-2','페르마의 원리','실제 광선의 경로는 가까운 경로들에 대해 광학적 경로 길이가 정류값을 갖는 경로다. 모든 경우에 전역적인 최단 시간이라고 말할 수는 없다. 균일한 영역에서는 직선, 평면 경계에서는 반사와 스넬의 굴절 법칙이 이 조건에서 나온다. 굴절률이 변하는 매질에서는 기하학적 거리보다 광학적 거리를 비교한다.');
add('5-1-3-1','페르마의 원리에 의한 반사의 법칙 해석','한 점에서 거울을 거쳐 다른 점에 도달하는 경로를 비교하자. 도착점을 거울 뒤에 대칭 이동시키면 반사 경로의 길이는 대칭점까지의 꺾인 경로 길이와 같아진다. 이 길이가 정류되는 경로에서 입사각과 반사각이 같다. 거울의 모든 위치에서 반사된 빛이 같은 관찰점에 도달하는 것은 아니다.');
add('5-1-5-1','무지개','햇빛이 물방울에서 굴절하고 내부 반사한 뒤 다시 굴절하며 나올 때 특정 편향각 부근에 빛이 모인다. 굴절률이 파장에 따라 달라 색마다 그 각도가 조금 다르다. 관찰자는 서로 다른 위치의 물방울에서 서로 다른 색을 보며, 무지개의 중심은 태양 반대 방향이다. 두 번 내부 반사한 빛은 색 순서가 반대인 이차 무지개를 만든다.');
add('5-1-5-1','빛의 분산','물질의 굴절률은 일반적으로 빛의 파장에 의존한다. 여러 파장의 빛이 같은 경계에 입사해도 굴절각이 달라 분리될 수 있다. 프리즘과 물방울은 이 분산을 이용한다. 분산이 색을 새로 만드는 것은 아니며 들어오는 빛에 포함된 파장 성분을 공간적으로 나누는 것이다.');
add('5-1-5-2','무지개의 모의실험','물방울의 서로 다른 높이에 입사하는 평행 광선을 추적해 출사 방향을 비교한다. 한 번 내부 반사하는 경로와 두 번 반사하는 경로를 나누고 파장마다 굴절률을 바꾸면 무지개의 색 순서를 확인할 수 있다. 광선이 많이 겹치는 방향과 모든 방향에 약하게 흩어지는 빛을 구별하자.');
add('5-1-6-1','색','물체의 색은 조명의 스펙트럼, 물체의 반사·투과 특성, 눈의 감도와 주변 환경에 의해 정해진다. 따라서 같은 물체도 조명이 달라지면 다른 색으로 보일 수 있다. 빛을 더하는 가산 혼합과 색소가 일부 파장을 흡수하는 감산 혼합을 구별해야 하며 색 이름만으로 스펙트럼을 유일하게 결정할 수 없다.');
add('5-1-6-1','빛의 분해','프리즘은 파장에 따른 굴절률 차이를, 회절격자는 파장에 따른 위상차를 이용해 빛의 성분을 공간적으로 분리한다. 흰빛을 분해하면 연속적인 파장 분포가 나타날 수 있고 원자의 방출광에서는 선 스펙트럼이 나타난다. 분리된 빛을 다시 합하면 원래의 색으로 돌아갈 수 있다.');
add('5-1-6-1','가시광선','사람의 눈이 감지하는 전자기파 영역을 가시광선이라 한다. 대략 수백 나노미터의 파장 범위이며 감도의 경계는 뚜렷하게 끊어지지 않는다. 진공의 파장과 매질 안의 파장을 구별하고, 굴절하더라도 진동수는 유지됨을 확인하자. 눈에 보이지 않는 적외선과 자외선도 같은 전자기파다.');
add('5-1-6-1','색의 인식','밝은 환경에서는 서로 다른 스펙트럼 감도를 가진 세 종류의 원추세포 신호가 색 인식에 기여한다. 어두운 환경에서는 막대세포의 역할이 커져 색 구별이 줄어든다. 서로 다른 스펙트럼도 같은 세 신호를 만들면 같은 색으로 보일 수 있으며, 뇌는 주변 밝기와 대비도 함께 처리한다.');
add('5-1-6-2','색의 명명','색 이름은 연속적인 색 공간을 몇 개의 범주로 나누는 언어적 약속이다. 같은 색상에서도 밝기와 채도가 달라지면 이름이 달라질 수 있고 조명이나 관찰 환경도 영향을 준다. 색을 일관되게 기록하려면 이름뿐 아니라 색 공간의 좌표와 기준 조명, 측정 조건을 함께 적는다.');
add('5-1-6-2','색의 측정','색을 측정할 때에는 스펙트럼과 표준 관찰자의 감도 함수를 결합해 삼자극값을 계산한다. 전체 밝기와 색도를 분리하면 서로 다른 밝기의 색을 비교할 수 있다. RGB 값은 사용한 원색과 색 공간에 의존하므로 수치 세 개만으로 기기 간 색을 동일하게 보장하지 않는다.');
add('5-1-6-3','색의 혼합과 보색','두 빛을 더하면 삼자극값이 더해지므로 색도는 두 색을 잇는 선분 위에 놓인다. 기준 백색을 만들도록 더할 수 있는 두 색을 보색이라 한다. 빛을 더하는 가산 혼합과 필터나 잉크가 파장을 제거하는 감산 혼합은 결과가 다르며 밝기도 함께 고려해야 한다.');
add('5-1-6-3','순도와 주파장','색도도에서 기준 백색점과 한 색을 잇는 선을 스펙트럼 궤적까지 연장하면 주파장을 정할 수 있다. 백색점에서의 상대 거리는 자극 순도를 나타낸다. 자주색처럼 단일 파장에 대응하지 않는 색은 보색 파장으로 표현한다. 주파장이 같아도 스펙트럼 전체가 같다는 뜻은 아니다.');
add('5-1-6-3','삼원색','세 원색의 양을 양수로 더하여 만들 수 있는 색도는 세 점이 이루는 삼각형 안에 있다. 원색을 바꾸면 그 삼각형과 재현 가능한 범위도 바뀐다. 어떤 실제 세 원색을 선택해도 모든 가시 색을 포함하지는 못한다. 원색은 자연이 유일하게 정해 놓은 세 파장이라기보다 표현 체계의 선택이다.');
add('5-1-6-3','색대역','색대역은 특정 화면이나 인쇄 과정이 재현할 수 있는 색의 범위다. 디스플레이의 원색과 최대·최소 밝기, 잉크와 종이의 반사 특성이 그 범위를 정한다. 색대역 밖의 색은 가까운 색으로 변환해야 하므로 화면과 인쇄의 결과가 달라질 수 있다. 색도 평면의 범위와 밝기를 포함한 전체 범위를 구별한다.');
add('5-1-6-4','빛의 삼원색','빨강·초록·파랑 빛의 밝기를 조절하면 가산 혼합으로 다양한 색을 표현할 수 있다. 빨강과 초록은 노랑, 초록과 파랑은 청록, 파랑과 빨강은 자홍 계열을 만든다. 세 빛으로 백색을 만들 때의 상대 세기는 원색 스펙트럼과 기준 백색에 따라 달라지며 같은 수치가 언제나 물리적으로 같은 밝기를 뜻하지 않는다.');
add('5-1-6-4','RGB 색모형','RGB는 세 원색의 성분으로 색을 표현한다. 원색의 색도, 기준 백색, 전달함수까지 지정해야 정확한 색 공간이 된다. 화면의 숫자 값은 보통 빛의 세기와 선형 비례하지 않으므로 물리적인 빛의 합을 계산할 때에는 선형 성분으로 변환해야 한다. 정수 범위는 저장 방식의 약속이다.');
add('5-1-6-5','색의 삼원색','청록·자홍·노랑 색소는 각각 주로 빨강·초록·파랑 성분을 흡수하는 감산 혼합의 기본색이다. 겹칠수록 남는 빛이 줄어 어두워진다. 실제 잉크는 이상적인 필터가 아니므로 세 색을 모두 섞어도 완전한 검정이 되지 않아 인쇄에서 검정 잉크를 추가한다. 빛의 RGB 가산 혼합과 반대 과정을 비교하자.');
add('5-1-6-6','HSV 색모형','HSV는 RGB 색을 색상·채도·명도의 좌표로 바꾸어 색 선택을 쉽게 한다. 색상은 원 둘레의 방향, 채도는 회색과의 차이, 명도는 가장 큰 RGB 성분에 대응한다. 명도가 같은 색이 같은 지각적 밝기를 갖는 것은 아니며, 무채색에서는 색상값이 의미를 잃는다.');
add('5-1-7-1','눈의 착시','시각은 망막의 신호를 그대로 복사하는 과정이 아니라 주변 대비와 경험을 이용해 장면을 해석하는 과정이다. 같은 선 길이나 회색값도 배경과 배열에 따라 다르게 보일 수 있다. 화면에서 물리적으로 같은 값을 가진 부분을 가려 비교하면 자극의 차이와 지각의 차이를 구별할 수 있다.');
add('5-2-1-1','구면경계에서의 빛의 굴절','구면의 각 위치에서는 법선 방향이 다르므로 입사 광선들이 서로 다른 각도로 굴절한다. 광축 가까이의 작은 각도에서는 물체 거리·상 거리·곡률반경·굴절률 사이의 근축 결상 관계를 얻는다. 축에서 멀리 입사하는 광선까지 같은 한 점에 모인다고 가정하면 구면수차를 놓치게 된다.');
add('5-2-1-1','허상','굴절하거나 반사한 빛이 실제로 한 점에서 만나지 않더라도, 관찰자가 빛의 진행 방향을 뒤로 연장하면 한 점에서 나온 것처럼 보일 수 있다. 그 점에 생기는 상을 허상이라 한다. 허상 위치에 스크린을 놓아 선명한 상을 받을 수는 없지만 눈은 그 방향에서 오는 빛을 통해 허상을 볼 수 있다.');
add('5-2-1-1','기하광학에서 부호의 약속','물체 거리·상 거리·곡률반경의 부호는 결상식을 일관되게 적용하기 위한 약속이다. 실제 물체와 실제 상, 가상의 물체와 허상을 구별하고 각 광학면에서의 빛 진행 방향을 확인한다. 서로 다른 교재의 부호 체계를 섞으면 물리적으로 같은 배치도 다른 결과를 줄 수 있으므로 한 식 안에서는 같은 기준을 유지한다.');
add('5-2-1-1','오목구면에서의 빛의 굴절','오목한 굴절면은 곡률 중심이 놓인 방향이 볼록면과 달라 곡률반경의 부호가 바뀐다. 그러나 수렴·발산 여부는 모양만이 아니라 양쪽 굴절률에도 의존한다. 입사와 출사 광선을 추적하여 실상과 허상을 판별하고 근축식의 거리 부호가 그 결과와 맞는지 확인하자.');
add('5-2-1-2','구면경계에서의 파면과 광선 모의실험','구면 경계의 각 위치에서 법선을 구하고 스넬의 법칙으로 광선을 추적한다. 광원을 가까이하거나 멀리하고 곡률반경을 바꾸어 상 위치를 비교하자. 광축 근처의 광선과 가장자리 광선이 다른 곳에 모이면 구면수차가 나타난 것이다. 파면의 모양과 광선 방향을 함께 보면 수렴과 발산을 구별할 수 있다.');
add('5-2-1-4','렌즈에서의 파면과 광선 모의실험','렌즈의 두 굴절면을 차례로 통과하는 광선을 추적하면 두께와 곡률의 영향을 직접 볼 수 있다. 물체 위치와 광선 입사 높이를 바꾸고 얇은 렌즈의 근축식과 비교한다. 두 면의 굴절을 한 평면의 꺾임으로 대체하는 근사가 언제 적절한지, 가장자리 광선에서 어디서 오차가 커지는지 살펴보자.');
add('5-2-2-2','구면거울의 모의실험','구면거울의 법선은 곡률 중심을 향하므로 각 광선에 반사의 법칙을 적용할 수 있다. 오목거울과 볼록거울에서 반사 광선의 실제 교차점과 뒤로 연장한 교차점을 비교한다. 광축에서 멀리 떨어진 평행 광선은 근축 초점과 다른 위치에 모일 수 있으므로 거울 공식의 작은 각도 조건을 확인한다.');
add('5-2-2-4','포물면거울을 조합한 장난감의 모의실험','마주 보는 오목 반사면은 한쪽의 물체에서 나온 빛을 다른 쪽 개구부 부근에 모아 공간에 실상을 만들 수 있다. 관찰 위치에 따라 물체가 그 자리에 있는 듯 보이지만 손으로 만질 수 있는 물질이 생긴 것은 아니다. 광선이 실제로 모이는 결상 장치와 파면을 기록·재생하는 홀로그래피를 구별한다.');
add('5-2-2-5','타원체거울','타원의 한 초점에서 나온 광선은 경계에서 반사한 뒤 다른 초점을 향한다. 두 초점에서 경계까지의 거리 합이 일정한 기하학적 성질로 이를 설명할 수 있다. 회전타원체는 이 집광 특성을 3차원으로 확장한다. 광원의 크기가 유한하거나 반사면이 이상적인 형태에서 벗어나면 빛은 한 점에 완벽하게 모이지 않는다.');
add('5-2-3-1','얇은 렌즈','렌즈 두께가 관련 거리보다 작고 광선이 광축에 가까우면 두 굴절면의 작용을 하나의 평면으로 근사할 수 있다. 얇은 렌즈 식은 물체 거리·상 거리·초점거리를 연결한다. 볼록한 모양이 항상 양의 초점거리인 것은 아니며 주변 매질과 렌즈의 상대 굴절률도 중요하다.');
add('5-2-3-1','광심','얇은 렌즈의 광심을 지나는 근축 광선은 진행 방향이 거의 바뀌지 않는 대표 광선으로 사용한다. 실제 두께가 있는 렌즈에서는 출사 방향이 평행해도 경로가 옆으로 이동할 수 있다. 광심을 지나는 직선을 정확한 모든 광선의 법칙으로 확대하지 말고 근축·얇은 렌즈 근사 안에서 사용한다.');
add('5-2-3-2','상의 작도법','광축에 평행한 광선, 물체 쪽 초점을 향하는 광선, 얇은 렌즈의 광심을 지나는 광선 중 두 개를 추적하면 상을 작도할 수 있다. 출사 광선이 실제로 만나면 실상이고 연장선만 만나면 허상이다. 물체의 각 점에서 나온 광선을 따로 추적하여 상의 방향과 배율을 확인한다.');
add('5-2-3-2','볼록렌즈의 결상에 대한 모의실험','실물체를 수렴 렌즈의 초점 밖에 놓으면 반대편에 도립 실상이 생긴다. 물체를 초점에 가까이하면 상은 멀어지고 커지며, 초점 안으로 넣으면 물체 쪽의 정립 허상이 된다. 물체를 움직일 때 상의 거리와 크기를 함께 기록하여 초점 앞뒤에서 부호가 바뀌는 의미를 확인하자.');
add('5-2-3-3','오목렌즈의 결상에 대한 모의실험','공기 속 발산 렌즈 앞에 실물체를 놓으면 출사 광선의 연장선이 물체 쪽에서 만나 축소된 정립 허상을 만든다. 물체를 멀리하면 허상은 렌즈의 물체 쪽 초점에 가까워진다. 다른 렌즈가 미리 수렴시키는 빛을 입사시키는 허물체 조건에서는 결과가 달라질 수 있으므로 실물체 조건을 명시한다.');
add('5-2-3-4','상의 왜곡','광축 방향으로 깊이를 가진 물체는 점마다 렌즈와의 거리가 달라 서로 다른 상 위치와 배율을 가진다. 따라서 하나의 횡배율만으로 입체 물체 전체를 설명하기 어렵다. 근축의 종배율은 횡배율과 다르며, 이 깊이 변형과 화면 주변 배율이 달라지는 광학적 왜곡수차를 구별해야 한다.');
add('5-2-3-4','상의 왜곡에 대한 모의실험','광축에 수직인 얇은 화살표와 깊이를 가진 물체를 따로 비교한다. 물체의 앞뒤 점이 각각 어디에 결상되는지 추적하고, 렌즈에 가까이할수록 앞뒤 거리와 가로 크기의 비가 어떻게 달라지는지 살펴보자. 모든 점을 같은 상 평면에 투영한 그림과 실제 3차원 결상 위치를 구별해야 한다.');
add('5-2-3-5','오목거울, 볼록거울의 결상','오목거울은 평행한 근축 광선을 앞쪽 초점으로 모으고 볼록거울은 뒤쪽 초점에서 퍼져 나온 것처럼 반사한다. 오목거울의 실물체가 초점 안에 있으면 확대된 정립 허상이 생기고, 볼록거울의 실물체에는 축소된 정립 허상이 생긴다. 거울은 빛 진행 방향을 반전시키므로 렌즈와 거리 부호 기준을 확인하며 비교한다.');
add('5-2-3-6','렌즈의 결상에 대한 모의실험','여러 렌즈·거울·조리개를 조합할 때에는 한 광학면에서 나온 광선을 다음 면의 입사광선으로 이어 추적한다. 중간 상이 다음 요소의 물체가 되며 실물체인지 허물체인지 판별해야 한다. 조리개는 빛을 제한하지만 자체가 초점을 만드는 요소는 아니다. 최종 상 위치와 통과한 광선 수를 따로 비교하자.');
add('5-2-4-1','허물체의 결상','입사 광선이 어떤 광학면을 만나기 전에 이미 그 뒤의 한 점을 향해 수렴하고 있다면 그 점은 그 면에 대한 허물체다. 허물체는 물질이 실제로 뒤에 놓였다는 뜻이 아니라 입사 파면의 수렴 조건을 나타낸다. 앞 렌즈가 만든 실상이 다음 렌즈 뒤에 위치하는 경우를 광선으로 추적하여 부호를 정한다.');
add('5-2-4-3','세 렌즈의 조합에 대한 모의실험','두 수렴 렌즈의 뒤초점과 앞초점을 일치시키면 평행광을 다시 평행광으로 만드는 빔 확대·축소계를 구성할 수 있다. 추가 렌즈로 최종 결상이나 빔 크기를 조절할 수 있지만 렌즈 간격과 중간 상 위치를 함께 계산해야 한다. 각 단계의 횡배율과 최종 배율의 곱 관계를 광선 추적으로 확인한다.');
add('5-2-5-1','눈의 구조','눈에서는 각막과 수정체가 빛을 굴절시켜 망막에 상을 만든다. 수정체의 곡률 변화는 서로 다른 거리의 물체에 초점을 맞추고 홍채는 동공 크기로 들어오는 빛을 조절한다. 망막의 광수용체는 빛을 신경 신호로 바꾼다. 눈을 하나의 얇은 렌즈로 보는 모형은 결상 원리를 설명하지만 실제 구조 전체를 대체하지 않는다.');
add('5-2-6-2','반사 프리즘','프리즘 내부의 경계에 빛이 임계각보다 큰 각도로 입사하면 전반사되어 진행 방향을 바꿀 수 있다. 적절한 면 배치는 빛을 직각으로 꺾거나 영상을 뒤집는 데 쓰인다. 전반사는 높은 굴절률에서 낮은 굴절률로 갈 때만 가능하며 접촉 물질이나 입사각이 바뀌면 조건도 바뀐다.');
add('5-2-6-2','일정편향 프리즘','일정편향 프리즘은 선택한 빛이 정해진 출력 방향으로 나오도록 굴절면과 반사면을 배치한다. 프리즘을 회전하면 분산 때문에 그 방향으로 통과하는 파장을 바꿀 수 있다. 기기의 입출력 방향을 유지하면서 스펙트럼을 훑는 데 유용하며, 일반 프리즘에서 모든 파장이 같은 방향으로 나온다는 뜻은 아니다.');
add('5-2-6-3','프리즘에 대한 모의실험','평행광이 프리즘의 첫 면과 둘째 면에서 굴절하는 경로를 추적한다. 꼭지각과 입사 방향을 바꾸어 전체 편향각을 비교하고, 특정 배치에서 나타나는 최소 편향을 찾는다. 내부 입사각이 임계각을 넘으면 출사 대신 전반사가 생길 수 있으므로 두 경계의 법선을 각각 사용해야 한다.');
add('5-2-6-4','분산 프리즘','프리즘에서는 파장별 굴절률 차이가 두 번의 굴절을 통해 출사 방향 차이로 나타난다. 보통 가시광의 정상 분산 영역에서는 짧은 파장 빛이 더 크게 편향된다. 재료와 꼭지각을 바꾸면 분산 정도가 달라지고, 파장에 따른 굴절률 관계는 물질마다 다르므로 하나의 직선으로 항상 근사할 수 없다.');
add('5-2-6-5','프리즘을 이용한 스펙트럼 측정','좁은 입구 슬릿의 빛을 평행하게 만든 뒤 프리즘으로 분산시키고 각 파장의 상 위치를 측정한다. 알려진 선 스펙트럼으로 각도와 파장을 교정하면 미지의 스펙트럼을 읽을 수 있다. 슬릿 폭을 줄이면 선 분리가 좋아질 수 있지만 빛이 줄어든다. 분광기의 분해능과 단순한 색 구별을 구분한다.');
add('5-2-7-1','전반사','굴절률이 큰 매질에서 작은 매질로 진행하는 빛은 임계각보다 큰 입사각에서 전반사된다. 손실이 없는 이상 경계에서는 입사 에너지가 반사되지만 경계 바깥에 감쇠하는 에바네슨트장이 존재한다. 따라서 바깥 전기장이 완전히 0이라고 해석하지 않는다. 각도는 경계면의 법선을 기준으로 잰다.');
add('5-2-7-1','광섬유','광섬유는 굴절률이 큰 코어를 더 작은 굴절률의 클래딩으로 둘러 빛을 유도한다. 광선 모형에서는 전반사의 반복으로 이해하지만 실제로는 경계조건을 만족하는 도파 모드가 전파된다. 너무 큰 굽힘, 흡수, 산란은 손실을 만들며 코어 크기와 파장은 가능한 모드 수를 정한다.');
add('5-2-7-2','광섬유의 원리에 대한 모의실험','입사 위치와 방향을 바꾸어 어떤 광선이 경계에서 전반사를 유지하는지 비교한다. 섬유를 구부리면 경계의 법선 방향이 바뀌어 일부 광선이 임계각 조건을 잃을 수 있다. 광선이 남는 경로와 빠져나가는 경로를 나누어 관찰하되, 미세 코어의 모드와 간섭은 단순 광선 그림 밖의 문제다.');
add('5-2-8-2','두꺼운 렌즈의 굴절에 대한 모의실험','두꺼운 렌즈에서는 첫 면의 굴절 후 렌즈 내부를 이동한 거리까지 포함하여 둘째 면에 입사하는 광선을 구한다. 두께·곡률·굴절률을 바꾸어 앞뒤 초점과 주요면의 위치를 비교한다. 물체와 상의 거리를 항상 렌즈의 중심에서 재는 얇은 렌즈 식을 그대로 사용하면 오차가 생길 수 있다.');
add('5-2-8-7','두 렌즈의 조합에 대한 광선과 파면 모의실험','첫 렌즈의 출사 파면은 두 렌즈 사이에서 전파한 뒤 둘째 렌즈에 입사한다. 렌즈 간격이 달라지면 중간 상과 최종 상의 위치가 모두 변한다. 광선과 파면을 함께 추적하고 근축 계산과 비교하면 렌즈 가장자리에서의 오차를 확인할 수 있다. 서로 다른 매질과 두께도 각 단계에 포함한다.');
add('5-2-9-3','프레넬 렌즈','프레넬 렌즈는 두꺼운 렌즈의 굴절면을 여러 고리 구역으로 나누어 얇은 구조로 만든다. 각 구역의 면 기울기가 광선을 집속하도록 설계되어 등대와 집광 장치에 쓰인다. 고리의 경계는 산란과 회절을 일으킬 수 있어 일반적인 영상용 렌즈와 같은 상 품질을 항상 제공하지 않는다.');
add('5-2-9-3','미소 렌즈 배열','작은 렌즈들을 배열하면 입사 파면의 각 부분을 별도의 초점으로 모을 수 있다. 평탄한 기준 파면의 초점 위치와 비교한 이동량으로 각 구역의 파면 기울기를 추정한다. 이 기울기들을 결합하면 파면을 복원할 수 있지만 일정한 전체 위상은 기울기 측정만으로 정해지지 않는다.');
add('5-2-9-4','조리개','조리개는 통과 가능한 광선의 범위를 제한한다. 개구를 줄이면 주변 광선에 의한 수차를 줄이고 피사계 심도를 늘릴 수 있지만 광량이 줄고 회절 퍼짐은 커진다. 따라서 무조건 작게 하는 것이 가장 선명한 상을 보장하지 않는다. 개구 조리개와 시야를 제한하는 시야 조리개의 역할을 구별한다.');
add('5-2-9-4','조리개의 역할에 대한 모의실험','렌즈 앞뒤에서 조리개를 이동하고 지름을 바꾸어 각 물체점에서 통과하는 광선 묶음을 비교한다. 중심점과 주변점의 빛이 다르게 잘리면 비네팅이 생긴다. 광량 감소와 수차 감소를 따로 관찰하고, 광선 모형에 보이지 않는 작은 개구의 회절 한계도 함께 고려한다.');
add('5-2-10-1','수차','수차는 실제 광학계의 상이 이상적인 근축 상에서 벗어나는 현상이다. 단색광에서도 구면수차·코마·비점수차·상면만곡·왜곡이 생길 수 있고, 여러 파장에서는 분산에 의한 색수차가 추가된다. 광선의 집속 오차와 회절에 의해 생기는 유한한 점상 크기는 원인이 다르다.');
add('5-2-10-2','코마수차','광축에서 벗어난 물체점의 광선이 개구 위치에 따라 서로 다른 배율과 상 위치를 가지면 꼬리가 달린 듯한 점상이 생긴다. 이를 코마수차라 한다. 렌즈의 곡률과 조리개 위치를 바꾸어 주변 광선의 분포를 비교한다. 축 위 점의 동심적인 구면수차 번짐과 비대칭적인 코마를 구별한다.');
add('5-2-10-2','비점수차','축 밖의 물체점에서는 주된 두 수직 단면의 광선이 서로 다른 위치에 초점을 만들 수 있다. 두 초점 사이에는 방향과 모양이 달라지는 점상이 나타난다. 한 평면만의 광선 추적은 이 차이를 놓칠 수 있다. 비점수차와 상면 자체가 굽는 상면만곡을 별개의 효과로 비교한다.');
add('5-2-10-3','렌즈의 수차 모의실험','렌즈의 앞뒤 곡률과 굴절률을 바꾸며 입사 높이가 다른 광선이 어디에 모이는지 비교한다. 광원을 축에서 벗어나게 하거나 렌즈를 기울이면 비대칭적인 점상도 관찰할 수 있다. 초점의 한 점만 찾기보다 여러 광선의 분포를 보고 구면수차와 코마의 차이를 판단한다.');
add('5-2-10-4','색수차','분산 때문에 렌즈의 굴절률과 초점거리는 파장별로 달라진다. 여러 색의 빛이 다른 축방향 위치에 모이거나 서로 다른 배율로 결상되어 색 번짐이 생긴다. 단일 렌즈의 근축 광선에서도 나타날 수 있으며, 단색 수차를 줄이는 것만으로는 없앨 수 없다. 재료가 다른 렌즈의 조합으로 일부 파장을 보정한다.');
add('5-2-10-5','렌즈의 색수차 모의실험','분산 특성이 다른 수렴 렌즈와 발산 렌즈를 조합하면 두 선택 파장의 초점을 일치시키는 색지움 렌즈를 만들 수 있다. 재료·곡률·간격을 따로 바꾸고 여러 파장의 초점 위치를 비교하자. 두 파장만 맞추어도 나머지 파장에서 잔여 색수차가 생길 수 있으므로 한 색의 선명도만으로 전체 보정을 평가하지 않는다.');
add('5-2-11-2','확대경의 모의실험','확대경은 물체를 수렴 렌즈의 초점 안에 놓아 확대된 정립 허상을 만든다. 눈에 보이는 확대 정도는 선형 상 크기보다 관찰 각도의 비로 평가한다. 물체 거리와 눈–렌즈 거리를 바꾸어 같은 물체가 차지하는 시야각을 비교하고, 눈이 이완된 조건과 가까운 허상에 초점을 맞추는 조건을 구별한다.');
add('5-2-11-4','현미경의 원리를 알아보는 모의실험','대물렌즈가 작은 물체의 확대된 실상을 만들고 대안렌즈는 그 중간 상을 확대경처럼 관찰하게 한다. 전체 배율에는 대물렌즈의 횡배율과 대안렌즈의 각배율이 함께 들어간다. 렌즈 간격과 물체 위치를 조절해 중간 상을 찾고 최종 허상 조건을 확인한다. 배율이 커지는 것과 분해능이 좋아지는 것은 같은 의미가 아니다.');
add('5-2-12-2','케플러식 굴절망원경의 원리를 알아보는 모의실험','먼 물체의 평행광을 대물렌즈가 초점면에 모으고 대안렌즈가 다시 평행광으로 내보낸다. 두 렌즈 초점면이 일치하는 이완 관찰 조건에서 각배율 크기는 초점거리의 비다. 중간 실상 때문에 상은 도립된다. 가까운 물체에는 렌즈 간격을 다시 맞추어야 하므로 무한거리 조건과 비교하자.');
add('5-2-12-3','뉴턴식 반사망원경','뉴턴식 망원경은 오목 주거울이 모으는 빛을 작은 기울어진 평면 부거울로 옆으로 꺾어 대안렌즈에서 관찰한다. 주거울의 반사에는 굴절률 분산이 없어 렌즈와 같은 색수차가 생기지 않는다. 그러나 반사면 모양, 정렬, 부거울의 가림은 상 품질과 회절 무늬에 영향을 준다.');
add('5-2-12-4','뉴턴식 반사망원경의 원리를 알아보는 모의실험','주거울에서 반사된 수렴 광선을 부거울로 꺾고 중간 상과 대안렌즈의 위치를 찾는다. 부거울이 기울어져도 주거울의 초점까지 광학적 경로가 이어짐을 확인한다. 주거울과 대안렌즈의 초점거리 비로 예상한 각배율을 광선 방향과 비교하고, 거울의 크기가 통과 광량에 미치는 영향을 살펴보자.');
add('5-2-12-5','쌍안경','쌍안경은 두 눈을 위한 망원경과 상을 바로 세우는 프리즘계를 결합한다. 프리즘의 여러 내부 반사가 광로를 접어 길이를 줄이고 도립된 중간 상의 방향을 바꾼다. 배율뿐 아니라 대물 구경, 출사동공, 두 눈 간격이 관찰 편의에 중요하다. 서로 다른 프리즘 방식에서는 반사 경로가 달라진다.');
add('5-2-12-6','쌍안경의 원리를 알아보는 모의실험','대물렌즈와 대안렌즈 사이의 여러 반사면을 추적하여 영상의 상하·좌우 방향을 비교한다. 반사 횟수만 세는 것보다 각 면의 방향에 따른 좌표 변환을 이어야 한다. 광로를 접었을 때 물리적 길이는 줄어도 초점 조건은 광학 경로를 따라 유지되어야 하며, 광선이 면 밖으로 빠지는지도 확인한다.');
add('5-3-1-1','편광','편광은 전자기파의 전기장 진동 방향과 위상 관계를 나타낸다. 진행 방향에 수직인 두 전기장 성분의 진폭과 상대 위상에 따라 선·원·타원편광이 된다. 비편광은 단순히 전기장이 없는 상태가 아니라 관측 시간 동안 방향과 위상 관계가 불규칙한 빛의 통계적 상태다.');
add('5-3-1-1','빛의 전파','진공의 평면 전자기파에서 전기장·자기장·전파 방향은 서로 수직이고 전기장과 자기장은 같은 위상으로 변한다. 에너지 흐름은 두 장의 벡터곱 방향이다. 그림의 정현파 곡선은 공간의 물체가 흔들리는 궤적이 아니라 각 위치의 장 성분을 나타낸다는 점을 구별한다.');
add('5-3-1-3','중첩과 편광','같은 진동수의 직교한 두 선편광을 안정한 위상 관계로 더하면 타원편광을 만들 수 있다. 위상차가 0 또는 π이면 선편광, 진폭이 같고 위상차가 사분의 일 주기이면 원편광이다. 상대 위상이 불안정한 두 빛을 더하는 것은 이런 결맞은 편광 합성과 다르다.');
add('5-3-1-5','중첩에 의한 편광의 형성 관찰','진행 방향에 수직인 두 전기장 성분의 진폭과 위상차를 각각 바꾸어 끝점 궤적을 비교한다. 한 위치의 시간 궤적과 같은 시각의 공간적 장 모양을 구별하면 원편광의 회전 의미가 명확해진다. 관찰 방향을 뒤집으면 회전이 반대로 보이므로 원편광의 손잡이성에는 방향 약속을 함께 적는다.');
add('5-3-1-6','자연광','독립적인 많은 원자의 방출광은 위상과 편광 방향이 서로 불규칙하여 흔히 비편광에 가깝다. 일정한 편광 방향을 가진 짧은 파동열이 섞여 있어도 긴 시간 평균에서는 한 방향을 선택하지 않을 수 있다. 반사·산란·흡수 과정을 거치면 자연광도 부분적으로 편광될 수 있다.');
add('5-3-2-2','도선격자 편광판','파장보다 촘촘한 도선격자에서는 도선과 나란한 전기장 성분이 전자를 움직여 강하게 반사되거나 흡수된다. 도선에 수직인 성분은 상대적으로 잘 통과하여 선편광을 만든다. 따라서 통과축을 도선 방향과 혼동하지 않는다. 격자 간격과 전도성이 작동 가능한 파장 범위를 제한한다.');
add('5-3-2-3','여러 가지 편광판','편광판은 방향에 따른 흡수·반사·굴절 차이로 한 편광 성분을 선택한다. 이색성 필름, 도선격자, 복굴절 프리즘은 서로 다른 원리를 사용한다. 이상적인 편광판 두 개를 직교시키면 빛이 차단되지만 실제 장치에는 유한한 소광비와 파장 의존성이 있다. 투과축과 흡수축의 표시를 확인한다.');
add('5-3-2-3','편광현미경','편광현미경은 편광자와 검광자 사이에 시료를 두어 시료의 이방성과 복굴절을 관찰한다. 시료가 두 성분에 주는 위상 지연 때문에 직교한 편광판 사이에서도 빛이 나타날 수 있다. 시료 두께·방향·파장에 따라 밝기와 색이 달라지므로 색만으로 물질을 유일하게 판별할 수는 없다.');
add('5-3-2-4','편광판의 작동','선편광의 전기장을 편광판의 투과축에 투영하면 출사 진폭을 구할 수 있다. 세기는 축 사이 각도의 코사인 제곱에 비례하는 말뤼스 법칙을 따른다. 비편광이 이상적인 편광판 하나를 통과하면 평균 세기는 절반이다. 진폭 투영과 세기 계산을 구별하며 여러 편광판을 순서대로 적용한다.');
add('5-3-3-1','산란된 빛의 편광','작은 입자의 전하가 입사광의 전기장에 의해 진동하면 쌍극자 복사를 만든다. 관찰 방향에 따라 보이는 진동 성분이 달라져 산란광은 편광될 수 있다. 이상적인 단일 레일리 산란에서 직각 방향의 빛은 강한 선편광을 보인다. 실제 하늘에서는 다중 산란과 입자 분포 때문에 단순 모형과 차이가 난다.');
add('5-3-4-1','결정에서의 빛의 전파','결정은 방향에 따라 전기장에 대한 물질의 응답이 다를 수 있다. 유전율을 하나의 수가 아니라 텐서로 표현하면 허용 편광과 전파속도를 구할 수 있다. 이방성 매질에서는 파벡터와 에너지 흐름 방향이 일치하지 않을 수 있다. 결정의 광축은 광학계의 대칭축이라는 기하광학 용어와 구별한다.');
add('5-3-4-1','복굴절','이방성 매질에서는 같은 진행 방향에 두 편광 모드가 서로 다른 굴절률을 가질 수 있다. 입사광이 두 모드를 모두 자극하면 서로 다른 경로 또는 위상으로 전파되어 두 상이나 편광 변화가 나타난다. 광축 방향에서는 두 모드의 굴절률이 같아지는 경우가 있다. 입사광의 편광에 따라 한 모드만 나타날 수도 있다.');
add('5-3-4-2','방해석','방해석은 탄산칼슘 결정으로 강한 복굴절을 보이는 대표적인 단축성 물질이다. 문자를 결정 아래에 놓으면 두 편광 모드가 만든 상을 볼 수 있다. 결정 방향을 바꾸면 상의 위치가 달라지고 편광판으로 두 상을 선택할 수 있다. 정상광선과 이상광선의 차이는 굴절률의 방향 의존성에서 나온다.');
add('5-3-4-2','광축의 성질','복굴절 결정의 광축은 그 방향으로 진행할 때 두 허용 편광 모드의 위상속도가 같아지는 방향이다. 단축성 결정은 하나의 광축 방향을, 이축성 결정은 두 방향을 가진다. 광축과 평행하게 진행하는 경우와 전기장이 광축에 나란한 경우는 다른 조건이므로 진행 방향과 편광 방향을 따로 적는다.');
add('5-3-4-4','파벡터 표면','고정된 진동수에서 허용 파벡터의 끝점들을 모으면 파벡터 표면이 된다. 등방성 매질에서는 구면이고 단축성 이방성 매질에서는 두 모드에 해당하는 구면과 회전타원체를 볼 수 있다. 경계에 평행한 파벡터 성분을 맞추면 굴절 방향을 구할 수 있고 에너지 흐름은 이 표면의 법선과 관련된다.');
add('5-3-4-5','단축성 결정들','단축성 결정에서는 정상 굴절률과 주 이상 굴절률의 크기 관계로 양성·음성 결정을 구별한다. 실제 이상 모드의 유효 굴절률은 진행 방향과 광축 사이 각도에 의존한다. 굴절률 차이와 두께를 알면 편광 성분의 위상 지연을 계산할 수 있으며, 재료의 투명 파장 범위도 선택에 중요하다.');
add('5-3-4-6','위상지연판 모의실험','선편광을 판의 두 주축 성분으로 나누면 서로 다른 굴절률 때문에 두 성분에 상대 위상이 쌓인다. 반파장판은 상대 위상 π, 사분파장판은 π/2를 준다. 입사 진폭이 같고 사분파장 지연이면 원편광을 만들 수 있다. 판의 축 각도와 두께를 바꾸어 진폭 분할과 위상 지연의 역할을 따로 비교한다.');
add('5-3-4-8','단축성 물질에서의 복굴절','단축성 경계에서 정상 모드는 일정한 정상 굴절률로 굴절하고 이상 모드는 광축 방향에 따른 유효 굴절률을 가진다. 이상광선의 에너지 방향은 파벡터 방향에서 벗어날 수 있다. 따라서 하나의 스넬식에 일정한 이상 굴절률을 대입하는 것만으로 모든 결정 배치를 설명하지 못한다.');
add('5-3-4-9','복굴절의 모의실험','입사각과 결정 광축 방향, 두 주 굴절률을 독립적으로 바꾸어 두 모드의 경로를 비교한다. 입사 편광을 바꾸면 각 모드에 들어가는 빛의 비율이 변한다. 파면의 법선 방향과 광선의 에너지 진행 방향을 구별하면 이상광선의 특이한 굴절을 이해할 수 있다. 광축에 나란한 진행에서는 분리가 사라지는지 확인한다.');
add('5-3-7-1','유도광학 효과','전기장·자기장·응력은 물질의 대칭성과 전자 응답을 바꾸어 굴절률·복굴절·광활성에 변화를 줄 수 있다. 이런 변화로 빛의 위상과 편광을 조절하거나 외부 물리량을 측정한다. 각 효과가 장에 선형인지 제곱에 비례하는지는 재료의 대칭성과 작용 방식에 따라 다르다.');
add('5-3-7-5','광자기기록장치','광자기 기록에서는 자기 상태를 정보로 저장하고 자화에 따른 반사광의 편광 변화를 읽는다. 기록 과정에서 국소 가열과 외부 자기장이 자기 상태를 바꾸는 데 사용될 수 있다. 판독 신호는 단순한 반사광 밝기가 아니라 편광 분석에서 얻는 차이일 수 있으며, 기록과 판독의 역할을 구별한다.');
add('5-3-7-7','광탄성 모의실험','응력을 받은 투명 물체의 복굴절은 편광 성분 사이에 위상 지연을 준다. 편광자와 검광자 사이에서 나타나는 명암이나 색 무늬로 응력 차이를 추정할 수 있다. 시료 두께와 재료 상수가 필요하며 한 무늬만으로 모든 응력 성분을 바로 결정하지는 못한다. 장치의 축을 돌려 밝기 변화를 비교한다.');
add('5-3-8-1','액정','액정은 분자가 위치상으로는 흐를 수 있지만 방향 등의 질서를 유지하는 상태다. 분자 배열에 따라 네마틱·스멕틱 등 여러 상이 있으며 광학적으로 이방성을 보일 수 있다. 표면 처리와 전기장으로 평균 분자 방향을 바꾸면 굴절률과 편광 전달을 조절할 수 있다. 고체 결정과 보통 등방성 액체의 중간적인 특성을 구별하자.');
add('5-3-8-3','액정표시장치','액정표시장치는 전압에 따른 분자 방향 변화를 편광판과 결합하여 투과 밝기를 조절한다. 액정이 빛을 직접 내는 것은 아니므로 일반적인 LCD에는 배경광이나 반사 조명이 필요하다. 색 필터와 각 화소의 밝기 제어로 영상을 만든다. 구동 방식과 분자 배향은 시야각·응답 시간·명암비에 영향을 준다.');
add('5-4-1-1','빛의 간섭','두 빛의 전기장을 더해 세기를 계산하면 개별 세기 외에 위상차에 의존하는 교차항이 생긴다. 측정 시간 동안 위상 관계가 유지되면 밝고 어두운 간섭무늬를 볼 수 있다. 편광이 완전히 직교하면 보통의 세기 검출에서 교차항이 사라진다. 공간 중첩만으로 선명한 간섭을 보장하지는 않는다.');
add('5-4-1-1','파동과 빛의 간섭','빛의 진동은 너무 빨라 눈이나 보통 검출기가 순간 전기장을 직접 따라가지 못한다. 시간 평균 세기를 측정해 공간적인 간섭무늬를 관찰한다. 광원의 파장 폭은 시간 결맞음과, 광원 크기는 공간 결맞음과 관련된다. 하나의 광원을 둘로 나누는 방법은 두 독립 광원보다 안정된 위상 관계를 만들기 쉽다.');
add('5-4-1-1','간섭과 회절','간섭과 회절은 모두 서로 다른 경로에서 온 파동의 중첩으로 계산된다. 보통 몇 개의 분리된 경로의 합을 간섭, 연속적인 개구의 합을 회절이라 부르지만 두 현상 사이에 엄격한 물리적 경계가 있는 것은 아니다. 이중슬릿에서는 두 슬릿의 간섭무늬가 각 슬릿의 회절 포락선 안에 나타난다.');
add('5-4-1-2','영의 이중슬릿 간섭','두 슬릿에서 나온 빛의 경로차에 따라 밝고 어두운 띠가 생긴다. 같은 위상의 조명에서 경로차가 파장의 정수배이면 밝고 반정수배이면 어둡다. 먼 스크린의 작은 각도에서는 띠 간격이 파장과 스크린 거리의 곱을 슬릿 간격으로 나눈 값에 가깝다. 실제 슬릿 폭의 회절도 함께 고려한다.');
add('5-4-1-2','마이컬슨 간섭계','빔 분할기로 나눈 두 빛을 서로 다른 팔의 거울에서 반사해 다시 합치면 광학적 경로차에 따른 간섭이 나타난다. 한 거울을 움직이면 왕복 경로는 이동량의 두 배만큼 변한다. 간섭 띠의 이동으로 작은 변위를 측정할 수 있다. 거울의 기울기와 광원의 결맞음도 무늬의 모양과 선명도를 결정한다.');
add('5-4-2-1','빛의 파동과 에너지','고전 전자기파의 에너지 흐름은 전기장과 자기장의 벡터곱으로 나타낸다. 단색 평면파의 평균 세기는 장 진폭의 제곱에 비례한다. 두 파의 장을 먼저 더한 뒤 제곱해야 간섭항이 나타난다. 광자 에너지가 진동수에 비례한다는 양자 관계와 고전 장의 진폭에 따른 전체 세기 변화를 구별한다.');
add('5-4-3-2','이중슬릿 간섭의 모의실험','스크린 한 점에 도달한 두 빛을 길이가 진폭, 방향이 위상인 벡터로 나타내어 합한다. 경로차를 바꾸면 두 위상자의 각도가 달라져 합성 길이가 변한다. 합성 진폭을 제곱해 밝기를 구하고 슬릿 간격과 파장에 따른 띠 간격을 비교한다. 두 빛의 세기가 다르면 최소점도 완전히 어둡지 않을 수 있다.');
add('5-4-3-2','다중슬릿 간섭','동일한 간격의 여러 슬릿은 각 방향에서 일정한 위상차를 가진 빛을 더한다. 주극대 방향에서는 모든 성분이 같은 위상으로 합쳐지고 슬릿 수가 많아질수록 봉우리가 좁아진다. 주극대 사이에는 작은 부극대가 존재할 수 있다. 전체 분포에는 각 슬릿의 유한한 폭에 의한 회절 포락선도 곱해진다.');
add('5-4-4-1','반사파의 위상변화','손실 없는 유전체에서 수직 입사하는 전기장 반사는 낮은 굴절률에서 높은 굴절률로 갈 때 부호가 뒤집히고 반대 방향에서는 유지된다. 비스듬한 입사, 편광, 전반사, 흡수성 매질에서는 위상 관계가 더 복잡하다. 얇은 막의 간섭에서는 전파 경로차와 각 반사의 위상 변화를 함께 더해야 한다.');
add('5-4-4-2','뉴턴 링','곡면 렌즈와 평판 사이의 얇은 공기층은 반지름에 따라 두께가 달라진다. 위아래 경계에서 반사된 두 빛의 경로차가 동심원 간섭무늬를 만든다. 이상적인 접촉점은 반사 위상차 때문에 반사광에서 어둡게 보인다. 고리 반지름의 제곱과 차수의 관계로 파장이나 곡률반경을 추정할 수 있다.');
add('5-4-4-2','기름막, 비누막의 간섭','얇은 막의 앞뒤 경계에서 반사된 빛은 막 안의 왕복 광학 거리와 반사 위상차에 따라 보강하거나 상쇄한다. 흰빛에서는 파장별 조건이 달라 두께와 관찰각에 따라 색이 변한다. 막 아래 물질의 굴절률도 반사 부호를 정하므로 모든 막에서 같은 밝음 조건을 적용하면 안 된다.');
add('5-4-5-2','패브리-페로 간섭계','서로 마주 보는 부분 반사면 사이에서 여러 번 왕복한 빛이 중첩된다. 왕복 위상이 정수 주기일 때 투과가 강해지고 높은 반사율에서는 공진 봉우리가 좁아진다. 판 사이 거리와 굴절률이 공진 주파수 간격을 정하며 반사율과 손실은 선폭과 투과 최대값을 결정한다.');
add('5-4-5-3','다층박막의 간섭','굴절률과 두께가 다른 막을 쌓으면 각 경계의 반사광이 여러 위상으로 더해진다. 층을 설계하여 특정 파장에서 반사를 줄이거나 높이고 투과 대역을 만들 수 있다. 각 층의 광학적 두께와 입사각·편광을 함께 고려해야 하며 반사율을 개별 경계의 값만 더해서 계산할 수 없다.');
add('5-4-5-6','패브리-페로 간섭필터','고반사 다층막 사이에 결함층 또는 공동을 넣으면 좁은 공진 투과 대역을 만들 수 있다. 공동의 광학적 길이가 중심 파장을 정하고 주변 반사 구조와 손실이 선폭을 정한다. 비스듬히 입사하면 중심 파장과 편광별 투과가 변할 수 있다. 좁은 투과 창과 넓은 반사 대역을 함께 확인한다.');
add('5-4-5-6','주기적인 다층박막의 모의실험','두 굴절률의 층을 반복하여 쌓고 층 두께와 반복 횟수를 바꾸어 반사·투과 스펙트럼을 비교한다. 사분파장 광학 두께 부근에서는 특정 대역의 반사가 강해질 수 있다. 반복 수를 늘리는 효과와 층 사이 굴절률 차이를 키우는 효과를 따로 살펴보고, 손실이 없는 모형에서는 반사와 투과 에너지의 합을 확인한다.');
add('5-5-1-1','회절','유한한 개구를 지난 빛은 여러 위치에서 나온 파의 중첩으로 퍼진다. 좁은 슬릿일수록 먼 거리의 중앙 봉우리가 넓어진다. 단일슬릿의 첫 최소각은 파장과 슬릿 폭의 비로 정해지며 작은 각도에서 중앙 폭이 그 비에 비례한다. 매우 좁은 슬릿에서는 광량 감소와 넓은 퍼짐을 함께 고려해야 한다.');
add('5-5-1-2','단일슬릿 회절의 모의실험','슬릿을 작은 구간으로 나누고 각 구간에서 스크린 점까지 도달하는 빛의 위상자를 더한다. 관찰각이 커지면 위상자들이 휘어진 합을 이루어 서로 상쇄할 수 있다. 구간 수를 늘려 연속 개구의 결과에 수렴하는지 확인하고, 진폭 합의 크기와 그 제곱인 세기를 구별한다.');
add('5-5-2-2','광학기구와 분해능','유한한 원형 개구는 이상적인 점광원도 에어리 무늬로 결상한다. 두 점의 상이 가까우면 무늬가 겹쳐 구별이 어려워진다. 회절 한계의 각 분해능은 파장에 비례하고 개구 지름에 반비례한다. 확대 배율을 늘려도 이미 겹친 정보를 새로 만들지는 못하며 수차·잡음도 실제 분해능에 영향을 준다.');
add('5-6-1-1','빛의 속성','빛은 에너지와 운동량을 전달하는 전자기적 현상이다. 전파와 간섭은 파동으로 설명할 수 있고 검출과 물질의 에너지 교환은 광자의 양자 관계가 필요하다. 눈에 보이는 빛은 전체 전자기 스펙트럼의 일부다. 하나의 고전적 입자 그림이나 물질 매질의 흔들림만으로 모든 성질을 설명할 수 없다.');
add('5-6-1-1','빛의 입자론과 파동론','반사·굴절을 설명하려는 초기 이론에서 빛을 입자나 파동으로 보는 관점이 경쟁했다. 간섭과 회절은 파동성을, 광전효과와 원자 전이는 양자적 에너지 교환을 드러낸다. 현대의 광자는 단순한 작은 공이 아니며 고전 파동과 고전 입자 중 하나를 모든 상황에 그대로 적용하는 것으로 이해해서는 안 된다.');
add('5-6-1-2','흑체복사','열평형의 이상적인 흑체는 입사하는 빛을 모두 흡수하며 방출 스펙트럼은 온도로 정해진다. 온도가 높아지면 방출 전력이 커지고 스펙트럼 봉우리가 짧은 파장 쪽으로 이동한다. 작은 구멍을 가진 공동은 흑체에 가까운 실험 모형이다. 실제 물질은 파장별 방사율 때문에 흑체와 다른 스펙트럼을 보일 수 있다.');
add('5-6-1-3','레이저의 특징','레이저는 유도방출로 빛을 증폭하고 모드 선택을 통해 높은 방향성과 결맞음을 얻는다. 좁은 스펙트럼과 집중 가능한 빔이 장점이지만 모든 레이저가 같은 선폭이나 연속 출력을 갖지는 않는다. 빔도 회절로 퍼지므로 완전한 평행선으로 영원히 유지되지 않는다. 출력·선폭·빔 품질을 서로 다른 특성으로 비교한다.');
add('5-6-1-3','빛의 흡수와 방출','두 에너지 준위 사이에서 광자 에너지가 준위 차이와 맞으면 흡수나 방출이 일어날 수 있다. 자발방출은 외부 광자 없이 일어나고 유도방출은 입사 모드에 빛을 더한다. 전이 확률은 준위 차이뿐 아니라 선택규칙과 결합 세기에도 의존한다. 들뜬 입자가 있다는 사실만으로 순증폭이 보장되지는 않는다.');
add('5-6-1-3','메이저','메이저는 마이크로파 영역에서 유도방출로 전자기파를 증폭하거나 발진시키는 장치다. 유효한 전이의 상위 준위에 더 많은 입자를 준비하는 반전분포와 적절한 모드 결합이 필요하다. 레이저와 기본 원리는 같지만 사용한 전이와 주파수 영역이 다르며, 초기 암모니아 메이저는 분자 준위를 이용했다.');
add('5-6-1-3','레이저','레이저 발진은 이득 매질의 증폭과 광학 공동의 되먹임이 손실을 이길 때 시작된다. 매질을 펌핑해 유효 전이에 반전분포를 만들고 공동이 일부 모드를 선택한다. 정상 출력에서는 이득 포화와 손실이 균형을 이룬다. 단순히 밝은 램프를 더 강하게 켜는 것과 유도방출 기반 발진을 구별한다.');
add('5-6-1-4','전자기파의 증폭','전자 회로는 입력 신호의 위상과 진동수를 유지하면서 외부 전원의 에너지를 신호에 전달해 전파를 증폭할 수 있다. 증폭률은 주파수에 의존하며 되먹임 조건이 맞으면 발진도 가능하다. 입력 에너지 자체가 복제되어 늘어나는 것이 아니라 전원의 에너지가 변환되는 과정이다.');
add('5-6-1-4','빛의 증폭','빛이 이득 매질을 지나며 유도방출을 일으키면 같은 모드의 광자가 늘어난다. 흡수가 더 강하면 오히려 약해지므로 유효 전이의 상·하위 준위 점유를 비교해야 한다. 증폭 에너지는 펌프가 공급하며 증폭이 커지면 반전분포가 줄어 포화된다. 열복사의 밝기 증가와 결맞은 빛의 순증폭은 다른 과정이다.');
add('5-6-1-5','원자 모형','원자의 전자는 핵 주변의 고전적인 원 궤적 대신 양자 상태로 기술된다. 파동함수의 절댓값 제곱은 위치 확률밀도를 주고 허용 에너지는 경계와 상호작용에 의해 정해진다. 오비탈의 모양은 에너지·각운동량 상태와 관련되지만 그림의 표면을 전자가 따라가는 궤도로 해석하지 않는다.');
add('5-6-1-5','원자에서 광자의 방출','원자가 높은 에너지 상태에서 낮은 상태로 전이하면 준위 차이에 해당하는 에너지의 광자를 방출할 수 있다. 역과정은 적절한 광자의 흡수다. 허용 전이는 선택규칙과 결합 행렬원소에 의해 정해지므로 모든 두 준위 사이에서 같은 확률로 일어나지는 않는다. 유한한 수명은 방출선의 유한한 폭과 관련된다.');
add('5-6-2-1','빛과 물질의 상호작용','빛과 원자는 흡수·자발방출·유도방출로 에너지를 주고받는다. 각 과정의 속도에는 준위 점유와 빛의 에너지 밀도가 들어간다. 열평형에서는 흡수와 방출의 균형이 플랑크 분포와 연결되며, 펌핑으로 평형에서 벗어난 반전분포를 만들면 순증폭이 가능해진다. 전이 선택규칙도 함께 고려한다.');
add('5-6-2-3','자발방출과 유도방출','독립적인 자발방출의 위상은 일반적으로 서로 안정하게 연결되지 않아 평균 세기가 더해진다. 유도방출은 입사한 모드에 광자를 더하여 결맞은 증폭을 가능하게 한다. 진폭을 단순히 입자 수만큼 더하는 그림은 공간·시간 결맞음과 에너지 공급 조건을 전제로 한다. 레이저 출력이 언제나 입자 수의 제곱으로 증가하는 것은 아니다.');
add('5-6-3-1','실제의 레이저','실제 레이저에는 펌프, 이득 매질, 모드 선택 또는 공동, 출력 결합과 손실이 필요하다. 펌프가 효율적으로 상위 레이저 준위를 채우고 하위 준위를 비워야 한다. 3준위와 4준위 구조는 발진 문턱과 점유 조건이 다르다. 전기·광학 에너지 공급량과 실제 출력 사이에는 다양한 손실이 있다.');
add('5-6-3-1','루비 레이저','루비 레이저는 산화알루미늄 결정에 포함된 크롬 이온의 준위를 이용한다. 광학 펌핑으로 높은 준위에 올린 뒤 비교적 오래 남는 준위에 입자를 모아 가시광 전이를 증폭한다. 대표적인 3준위 레이저여서 상당한 펌프가 필요하며 초기 장치는 펄스 방식으로 동작했다. 결정 자체의 색과 레이저 전이 파장을 구별한다.');
add('5-6-3-2','헬륨-네온 레이저','방전으로 들뜬 헬륨 원자는 충돌을 통해 네온 원자에 에너지를 전달할 수 있다. 네온의 적절한 준위에서 반전분포를 만들고 공동이 선택한 전이로 발진한다. 기체의 혼합과 충돌 경로는 펌핑 효율을 정한다. 대표적인 붉은 출력 외에도 다른 전이가 가능하므로 모든 헬륨–네온 레이저의 파장이 같지는 않다.');
add('5-6-3-3','이산화탄소 레이저','이산화탄소 레이저는 분자의 진동·회전 준위를 이용해 적외선을 낸다. 혼합 기체에서 질소의 진동 에너지가 이산화탄소에 전달되어 펌핑을 돕고 다른 성분은 하위 준위 이완과 열 제거에 기여한다. 전자 준위만 사용하는 원자 레이저와 달리 분자 운동 모드를 구별해야 한다. 출력과 효율은 방전·열관리·공동 조건에 의존한다.');
add('5-6-3-4','반도체 레이저','반도체 레이저는 전자와 정공을 주입하여 활성 영역에서 유도방출 이득을 만든다. 밴드 구조와 광학 도파 구조가 방출 파장과 모드를 정한다. 작은 크기와 전기 구동이 장점이지만 효율이 완벽한 것은 아니며 비복사 재결합과 열 손실이 있다. 문턱 아래의 발광과 문턱 위의 레이저 발진을 구별한다.');
add('5-6-4-1','빛의 공명상태','광학 공동의 왕복 위상이 일정 조건을 만족하면 장이 스스로 일관되게 재현되는 모드가 존재한다. 거울 간 거리와 굴절률은 종방향 모드의 간격을 정하고 개구와 곡률은 횡방향 모드를 선택한다. 공진 모드가 있다는 사실만으로 레이저가 발진하지는 않으며 매질 이득이 그 모드의 손실을 이겨야 한다.');
add('5-6-5-1','빔의 진행 모의실험','유한한 폭의 빔은 회절 때문에 진행하면서 퍼진다. 빔 허리를 좁게 만들수록 원거리 퍼짐각이 커지는 관계를 비교하자. 렌즈는 파면 곡률을 바꾸어 새 빔 허리를 만들 수 있지만 회절 한계를 없애지는 않는다. 광선 한 줄의 경로와 빔 전체의 폭·위상 분포는 다른 정보다.');
add('5-6-5-1','가로방향 진동 모드','레이저 공동의 횡모드는 광축에 수직인 단면에서의 장 분포를 나타낸다. 기본 가우스 모드는 가운데 하나의 봉우리를 가지며 높은 모드에는 마디와 여러 봉우리가 나타난다. 거울 곡률·개구·정렬·펌프 분포가 모드 선택에 영향을 준다. 횡모드 번호와 종방향 공진 주파수 번호를 구별한다.');
add('5-6-5-3','가우스 빔의 그래프','가우스 빔은 허리에서 최소 반경을 갖고 멀어지면서 넓어진다. 파장과 허리 반경이 정해지면 레일리 길이와 원거리 퍼짐각이 연결된다. 반경을 정의할 때 장 진폭 또는 세기의 감소 기준을 명시해야 한다. 여러 파장이나 허리 크기의 곡선을 비교하며 축방향 거리와 횡방향 세기를 다른 축으로 읽는다.');
add('5-6-6-1','게인 스위치','게인 스위칭은 펌프를 시간에 따라 바꾸어 이득이 발진 문턱을 넘는 순간에 짧은 출력을 얻는 방식이다. 반전분포가 먼저 쌓이고 광자 수가 증가한 뒤 이득이 소모되며 펄스가 나타난다. 펌프의 시간 폭과 레이저 펄스 폭이 반드시 같지는 않다. 공동 손실을 바꾸는 큐 스위칭과 작동 변수를 구별한다.');
add('5-6-6-1','큐 스위칭','큐 스위칭에서는 처음 공동 손실을 크게 하여 발진을 억제하고 매질에 에너지를 저장한다. 손실을 빠르게 줄이면 저장된 반전분포가 짧은 빛 펄스로 소모된다. 큰 최대 출력과 펄스 에너지는 다른 양이다. 펌프를 바꾸는 게인 스위칭이나 여러 모드의 위상을 맞추는 모드 동기화와 구별한다.');
add('5-6-7-1','홀로그래피의 특성','홀로그래피는 물체파와 기준파의 간섭무늬를 기록하여 물체파의 위상 정보를 강도 기록에 담는다. 적절한 조명으로 기록물을 비추면 회절로 물체의 파면을 재생할 수 있다. 단순한 평면 사진과 달리 시점에 따른 정보를 가질 수 있지만 재생 품질은 기록 개구·매질·조명 조건에 의해 제한된다.');
add('5-6-7-1','회절격자와 홀로그램','두 평면파의 간섭무늬는 일정한 간격의 격자를 만든다. 이 격자를 기준파로 조명하면 여러 회절차수 중 하나가 원래 물체파 방향으로 진행할 수 있다. 물체파가 복잡하면 국소 격자의 간격과 방향도 공간에 따라 달라진다. 회절격자는 파면 정보를 재생하는 홀로그램의 가장 단순한 예로 볼 수 있다.');
add('5-6-7-2','파면 정보의 기록','보통 검출기는 전기장 위상을 직접 기록하지 못하지만 알려진 기준파와 합치면 위상 차이가 간섭 명암에 나타난다. 물체파의 진폭과 기준파에 대한 위상 관계가 기록 매질의 변화로 저장된다. 노출 중 진동이나 위상 변동이 크면 무늬가 흐려지므로 기계적 안정과 결맞음이 필요하다.');
add('5-6-7-2','파면의 재생','기록된 홀로그램에 적절한 기준파를 다시 비추면 회절된 일부 빛이 원래 물체파와 같은 파면을 이룬다. 다른 회절 성분이나 직접 투과광도 함께 나올 수 있다. 재생광의 파장과 방향을 바꾸면 상의 크기와 위치가 달라질 수 있으므로 원래 기록 조건과 재생 조건을 함께 비교한다.');
add('5-6-7-2','구면파의 기록과 재생','점광원의 구면파와 평면 기준파가 만나면 위치에 따라 간격이 변하는 간섭무늬가 생긴다. 이 무늬를 다시 조명하면 수렴하거나 발산하는 구면파를 얻어 점상을 재생할 수 있다. 여러 점의 물체는 각 점에서 온 장의 합으로 기록되며, 한 점의 기하학적 경로와 전체 물체파의 중첩을 구별한다.');
add('5-6-7-3','투과형 홀로그래피 촬영장치','레이저 빛을 물체 조명과 기준파로 나누고 두 파가 같은 쪽에서 기록판에 만나도록 구성한다. 공간 필터와 빔 확대는 조명 파면을 다듬고 거울은 경로를 정한다. 기록 중 경로차가 결맞음 범위 안에 있어야 한다. 재생에서는 보통 기록판을 통과하는 회절광으로 상을 관찰한다.');
add('5-6-7-3','반사형 홀로그래피','물체파와 기준파가 기록층의 서로 반대쪽에서 만나면 두께 방향으로 촘촘한 간섭 구조를 만들 수 있다. 충분히 두꺼운 기록층은 브래그 선택성으로 특정 파장과 방향을 강하게 반사하여 파면을 재생한다. 이런 선택성은 백색광 재생을 가능하게 할 수 있지만 모든 기록 조건에서 자동으로 같은 결과가 나오지는 않는다.');
add('5-6-7-3','반사형 홀로그래피 촬영장치','기준파와 물체파를 기록판의 반대쪽에서 만나게 배치하고 두께 방향 간섭무늬를 안정하게 기록한다. 노출 뒤 매질의 두께나 굴절률이 변하면 재생 파장도 이동할 수 있다. 투과형과 달리 재생광이 반사되는 쪽을 관찰하며, 광로 배치와 기록층의 부피 구조를 함께 이해한다.');
add('5-6-7-4','홀로그래피의 응용','홀로그램은 입체 영상뿐 아니라 보안 표시, 파면 제어, 변형 측정, 광학 정보 저장에 활용된다. 응용마다 기록 매질과 재생 조건이 다르다. 물체의 작은 변형 전후 파면을 간섭시키면 변위를 정밀하게 비교할 수 있다. 회절로 파면을 재생하는 장치와 단지 입체적으로 보이는 다른 장치를 구별한다.');
add('5-6-7-4','렌티쿨러 렌즈','렌티쿨러 영상은 작은 원통 렌즈 배열 아래에 시점별 영상을 나누어 배치한다. 관찰 방향에 따라 다른 영상이 눈에 들어와 입체감이나 움직임을 느끼게 한다. 이 방식은 빛의 위상을 기록하는 홀로그래피가 아니다. 렌즈 간격·인쇄 정렬·관찰 거리의 오차는 영상 혼합과 흐림을 만든다.');
add('5-6-7-4','홀로그래피 광학소자','특정 입사파를 원하는 출사파로 바꾸는 간섭 구조를 기록하면 렌즈나 빔 분할기와 비슷한 역할을 하는 회절 소자를 만들 수 있다. 표면 형상만으로 작동하는 굴절 렌즈와 달리 파장·입사각 선택성이 강할 수 있다. 기록한 두 파면과 실제 사용 조건을 연결하여 소자의 집속과 편향을 해석한다.');
add('5-6-7-5','홀로그램','홀로그램의 한 부분에도 여러 물체점에서 온 빛이 기록될 수 있어 잘라낸 조각으로도 전체 물체의 일부 시야를 재생할 수 있다. 그러나 작은 조각은 개구가 줄어 밝기·분해능·시점 범위가 제한된다. 모든 조각이 언제나 완전한 동일 영상을 가진다는 표현은 피하고 기록 기하와 가림을 함께 고려한다.');
add('5-6-7-5','홀로그램 데이터 기록','부피 기록 매질에 여러 기준파 조건으로 데이터를 중첩 기록하고 선택한 기준파로 하나의 페이지를 재생할 수 있다. 각도·파장 등의 다중화와 브래그 선택성이 정보를 구별한다. 저장량은 매질의 동적 범위와 잡음·교차간섭·검출 분해능에 의해 제한되므로 기록 개수만으로 성능을 평가하지 않는다.');
add('5-6-7-6','홀로그램 스캐너','회절 소자를 움직이거나 회전하면 입사 빔의 출사 방향과 집속 위치를 바꾸어 스캔할 수 있다. 반복된 회절 구조는 바코드 등을 훑는 광학 경로를 만들 수 있다. 이동에 따른 상 위치 변화를 광선과 파면으로 비교하고, 반사 검출 신호에서 공간 패턴을 읽는 과정과 빔을 움직이는 과정을 구별한다.');
add('6-1-1-1','운동의 관찰','물체의 위치와 속도는 관찰자가 선택한 기준계에 따라 달라진다. 달리는 차 안의 공은 차에 대해 정지해도 지면에서는 움직인다. 물리적 사건은 같지만 좌표로 기록한 값이 달라지는 것이다. 서로 등속 운동하는 기준계에서 같은 실험을 비교할 때에는 위치뿐 아니라 시간과 측정 절차도 함께 지정해야 한다.');
add('6-1-1-2','빛의 속력과 에테르','소리에는 물질 매질이 필요하지만 진공의 빛에 같은 성질의 매질을 가정할 필요는 없다. 역사적인 에테르 모형은 지구의 운동에 따른 빛 속도의 방향 차이를 예상했지만 그런 효과는 확인되지 않았다. 이 결과를 단순한 파동의 매질 바람과 구별하고, 관성계에서의 진공 광속을 기준으로 새 시공간 관계를 이해한다.');
add('6-1-1-3','아인슈타인의 가설','특수상대성이론은 모든 관성계에서 물리법칙이 같은 형태이며 진공 광속이 광원 운동과 무관하게 같다는 두 원리에 기반한다. 이 두 조건을 함께 만족시키려면 시간과 공간 좌표가 서로 연결되어 변환되어야 한다. 느린 속도에서는 뉴턴역학의 관계가 좋은 근사가 되지만 빛에 고전적인 속도 덧셈을 적용할 수 없다.');
add('6-1-2-1','시공간연속체','하나의 사건은 일어난 위치와 시각을 함께 지정해야 한다. 서로 다른 관성계는 같은 사건에 다른 공간·시간 좌표를 붙이지만 시공간 간격의 관계는 보존된다. 공간에 배치된 시계가 한 기준계에서 동기화되었다고 다른 움직이는 기준계에서도 같은 동시성을 가진다는 뜻은 아니다.');
add('6-1-2-1','동시성','멀리 떨어진 두 사건이 동시에 일어났는지는 빛이 눈에 동시에 도착했는지만으로 결정할 수 없다. 신호 이동 시간을 보정하고 같은 기준계의 동기화된 시계를 사용해야 한다. 한 관성계에서 동시인 두 사건은 상대 운동하는 기준계에서는 일반적으로 동시가 아니다. 이는 실제 사건을 바꾸는 것이 아니라 시간 좌표의 관계다.');
add('6-1-2-1','시계 맞추기','한 지점에서 신호를 보내고 다른 지점에서 반사해 돌아오는 시각을 측정하면 왕복 시간의 절반으로 먼 시계의 동기화를 정의할 수 있다. 이 절차는 같은 관성계의 진공 광속과 신호 지연을 이용한다. 빛을 받는 순간 모든 시계를 같은 숫자로 맞추는 방식은 거리마다 다른 전파 시간을 무시하므로 동기화가 아니다.');
add('6-1-4-1','길이가 짧아진다!','물체가 정지한 기준계에서 잰 길이는 고유길이다. 물체가 움직이는 기준계에서 같은 시각의 앞뒤 위치를 재면 운동 방향의 길이가 고유길이보다 짧다. 속도가 커질수록 로렌츠 인자가 커져 수축이 두드러진다. 물체 자체가 자기 기준계에서 눌리거나 찌그러졌다는 의미는 아니다.');
add('6-1-4-1','길이의 측정','움직이는 물체의 길이는 두 끝의 위치를 측정 기준계에서 동시에 기록해야 한다. 서로 다른 시각에 찍은 위치 차이에는 그 사이의 이동이 섞인다. 고유길이 측정과 움직이는 길이 측정은 각각 다른 기준계의 동시 조건을 사용한다. 이 절차를 명시해야 서로가 상대 물체를 짧게 측정하는 결과를 이해할 수 있다.');
add('6-1-4-2','길이수축과 겉보기 모양','길이수축은 같은 시각의 위치 측정에 대한 결과이고 사진은 같은 도착 시각에 눈에 들어온 빛을 모은 것이다. 물체의 먼 부분에서 온 빛은 더 일찍 방출되었으므로 사진 속 모양은 수축된 좌표 모양과 다를 수 있다. 물체의 속도와 거리, 신호 방출 시각을 함께 계산하여 두 관찰을 구별한다.');
add('6-1-4-2','옆으로 운동하는 물체의 겉보기 모양','옆으로 빠르게 이동하는 물체의 각 부분은 관찰자까지 거리가 달라 서로 다른 시각의 모습을 보낸다. 이 시간 지연과 광행차 때문에 사진에는 회전하거나 비틀린 듯한 모양이 나타날 수 있다. 같은 시각의 좌표 그림을 단순히 운동 방향으로 압축한 것만으로 실제 보이는 영상을 얻을 수는 없다.');
add('6-1-4-2','앞뒤로 운동하는 물체의 겉보기 모양','관찰자를 향하거나 멀어지는 물체에서는 앞뒤 부분의 빛 이동 시간과 물체 운동이 함께 작용한다. 다가오는 경우와 멀어지는 경우의 겉보기 길이는 서로 다를 수 있다. 동시에 방출된 빛과 동시에 도착한 빛을 따로 추적하여 좌표상 길이수축·광행차·도플러 변화가 영상에 주는 영향을 나누어 보자.');
add('6-1-4-3','겉보기 모양 모의실험','빠르게 움직이는 관찰자가 보는 장면을 만들려면 각 방향의 빛에 로렌츠 변환과 광행차를 적용해야 한다. 색에는 도플러 변화, 밝기에는 상대론적 집중 효과도 생길 수 있다. 속도를 낮춰 일상적인 장면으로 돌아오는지 확인하고, 왜곡된 영상과 같은 시각의 물체 좌표를 별개의 그림으로 비교한다.');
add('6-1-5-3','시공간 좌표와 로렌츠 변환','시공간 도표에서 시간축은 한 위치에 머무는 관찰자의 세계선이고 공간축은 그 기준계의 동시 사건들을 나타낸다. 상대 운동하는 기준계의 두 축은 기울어지지만 유클리드 평면의 단순한 회전은 아니다. 빛의 세계선과 불변 간격을 기준으로 좌표 눈금을 읽고, 한 사건의 두 좌표가 같은 점을 가리키는지 확인한다.');
add('6-1-6-1','우주팽창의 증거','먼 은하의 스펙트럼선은 많은 경우 긴 파장 쪽으로 이동한다. 거리와 적색편이의 관계는 우주 팽창의 주요 증거다. 가까운 천체의 고유운동에 의한 도플러 이동과 우주론적 적색편이를 구별하며, 큰 거리에서는 공간의 팽창과 빛의 전파 역사를 포함해야 한다. 모든 적색편이를 단순한 특수상대론적 속도로 바꾸지는 않는다.');
add('6-1-7-1','쌍둥이 역설','왕복 여행자는 지구에 머문 쌍둥이와 다른 시공간 경로를 지나므로 다시 만났을 때 고유시간이 다를 수 있다. 여행 중 방향 전환은 두 관찰자의 경로가 대칭적이지 않음을 드러낸다. 한 관성계에서 상대 시계가 느리다는 문장만 양쪽에 적용하지 말고 출발·전환·재회의 사건 사이 고유시간을 각각 합한다.');
add('6-1-7-3','차고와 막대기의 역설','움직이는 막대가 차고 기준계에서는 수축하여 잠시 양문 안에 들어갈 수 있다. 막대 기준계에서는 차고가 더 짧지만 두 문을 닫는 사건이 동시가 아니므로 모순이 없다. 문 닫힘을 하나의 사건처럼 묶지 않고 각각의 시공간 좌표로 변환해야 한다. 실제 충돌과 변형은 정보가 유한한 속도로 전달되는 별도 동역학 문제다.');
add('6-1-8-1','뉴턴역학과 상대론적 역학','작은 속도에서 뉴턴역학은 상대론적 관계의 근사로 유지된다. 빠른 속도에서는 운동량·에너지의 로렌츠 변환과 빛보다 느린 물체의 고유질량을 사용해야 한다. 전체 에너지에는 정지에너지가 포함되며 운동에너지는 이를 뺀 값이다. 에너지를 계속 공급해도 질량 있는 입자를 광속에 도달시키는 데 유한한 에너지로는 충분하지 않다.');
add('6-1-9-1','등가원리','작은 시공간 영역에서 자유낙하하는 실험실은 중력의 국소 효과를 제거한 관성계처럼 행동한다. 반대로 가속하는 실험실에서는 중력과 비슷한 효과를 느낀다. 그러나 넓은 영역의 조석력은 좌표 선택으로 모두 없앨 수 없으므로 등가원리를 지구 전체에서 모든 중력 효과가 사라진다는 뜻으로 해석하지 않는다.');
add('6-1-9-1','빛과 중력','가속하는 관찰자에게 빛의 경로가 휘어 보이는 사고실험은 중력과 빛의 관계를 이해하는 출발점이다. 일반상대성이론에서는 빛이 휘어진 시공간의 널 측지선을 따른다. 중력 렌즈와 중력 적색편이는 그 결과다. 빛의 정지질량이 0이라는 사실만으로 중력과 상호작용하지 않는다고 결론내리지 않는다.');
add('6-1-9-2','일반상대성이론','일반상대성이론은 물질과 에너지의 분포가 시공간 곡률과 연결되고 자유 입자가 그 기하학을 따라 운동하는 이론이다. 중력을 보통 공간의 힘만으로 나타내는 뉴턴 모형보다 넓은 범위를 다룬다. 약한 장과 느린 운동에서는 뉴턴의 결과에 가까워진다. 공간의 그림만으로 시간 성분과 전체 시공간 곡률을 대체하지 않는다.');
add('6-1-9-2','일반상대성이론의 확인','태양 근처를 지나는 별빛의 편향, 수성의 근일점 이동, 중력에 따른 시계 주파수 변화는 일반상대론을 시험하는 서로 다른 관측이다. 일식 때는 태양 주변 별의 겉보기 위치를 다른 시기의 기준 위치와 비교할 수 있다. 관측 오차와 다른 원인을 평가한 뒤 예측값과 비교해야 한다.');
add('6-2-1-4','광전효과','금속에 빛을 비추면 광자가 전자에 에너지를 전달하여 전자를 밖으로 방출할 수 있다. 한 광자 과정에서 최대 운동에너지는 광자 에너지에서 일함수를 뺀 값이다. 문턱 이하의 진동수에서는 세기만 높여 같은 과정을 일으킬 수 없다. 빛의 세기는 주로 방출 전자 수, 진동수는 에너지 한계에 영향을 준다.');
add('6-2-1-4','빛의 이중성','빛의 간섭과 회절은 전파 진폭의 중첩을, 광전효과는 검출에서의 에너지 양자화를 보여 준다. 같은 빛을 서로 독립적인 고전 파동과 작은 공으로 번갈아 바꾸어 생각하는 것만으로는 충분하지 않다. 실험의 준비·전파·측정을 하나의 양자 설명으로 연결하며, 어떤 물리량을 측정했는지 먼저 명시한다.');
add('6-2-2-1','빛의 스펙트럼','분광기로 빛을 나누면 파장이나 진동수에 따른 세기 분포를 얻는다. 열복사의 연속 스펙트럼과 희박한 원자의 선 스펙트럼은 다른 생성 과정을 반영한다. 흡수선은 배경광의 일부 파장이 제거된 결과다. 파장당 세기와 진동수당 세기는 변수 변환 계수가 달라 곡선 모양과 봉우리 위치도 다를 수 있다.');
add('6-2-3-1','원소설','물질은 여러 원소의 원자로 구성되며 화학 반응에서는 원자들이 재배열되어 다른 분자를 만든다. 원소의 종류는 원자핵의 양성자 수로 구별된다. 원자는 더 작은 구성 요소를 가지므로 가장 기본적인 불가분 입자는 아니다. 원소의 화학적 주기성은 전자 배열과 관련되고 동위원소는 같은 원소에서 중성자 수가 다른 경우다.');
add('6-2-3-1','톰슨의 원자모형','전자 발견 뒤 톰슨은 양전하가 퍼진 원자 내부에 음전하 전자가 들어 있는 모형을 제안했다. 원자의 전체 중성과 전자의 존재를 함께 설명하려는 시도였다. 그러나 양전하가 넓게 분포하면 무거운 입자의 큰 각도 산란을 설명하기 어렵다. 역사적 모형의 가정과 이후 실험이 보여 준 한계를 구별한다.');
add('6-2-3-2','러더퍼드의 산란 실험','얇은 금속막을 통과한 알파입자의 대부분은 거의 직진했지만 일부는 크게 방향이 바뀌었다. 이는 양전하와 대부분의 질량이 작은 핵에 집중된 모형과 부합한다. 입사 위치에 따른 쿨롱 힘과 산란각을 비교하며, 산란 분포에서 추론한 내부 구조와 직접 찍은 원자 사진은 다른 종류의 정보임을 확인한다.');
add('6-2-3-2','러더퍼드의 원자모형','러더퍼드 모형은 작은 양전하 핵과 그 주변 전자를 도입했다. 원자의 크기와 핵의 크기가 크게 다르다는 점이 산란 결과를 설명한다. 그러나 전자가 고전적인 궤도에서 가속하면 복사해야 하므로 원자의 안정성과 선 스펙트럼은 이 모형만으로 설명되지 않는다. 핵의 존재와 전자 운동의 양자 기술을 별개 발전으로 이해한다.');
add('6-2-3-5','러더퍼드 원자모형의 문제점','고전 전자기학에서 원운동하는 전하는 가속하며 에너지를 복사한다. 핵 주변의 전자가 계속 에너지를 잃으면 궤도가 줄어 안정한 원자가 유지되지 않는다. 또 연속적인 궤도 에너지는 관측된 이산적인 스펙트럼과 맞지 않는다. 이 문제는 단순한 작은 보정이 아니라 원자 상태에 대한 새로운 양자 설명을 요구했다.');
add('6-2-3-6','보어의 가설과 원자모형','보어는 특정 정상 궤도에서는 전자가 복사하지 않고, 상태 사이의 전이에서 에너지 차이에 해당하는 광자를 주고받는다고 가정했다. 각운동량 양자화는 수소의 에너지와 스펙트럼을 설명하는 데 성공했다. 그러나 궤도 가정 자체는 현대 양자역학의 일반적인 설명이 아니며 전자가 많은 원자에는 그대로 적용되지 않는다.');
add('6-2-4-2','보어의 이론의 한계','보어 모형은 수소와 수소형 이온의 주요 에너지 관계를 설명하지만 다전자 원자와 전이 세기·세부 분열을 일반적으로 계산하지 못한다. 고전 궤도에 양자 조건을 덧붙인 절차는 왜 그 상태가 존재하는지를 충분히 설명하지 않는다. 파동함수와 연산자를 사용하는 양자역학은 안정한 상태와 전이를 더 일관되게 다룬다.');
add('6-2-4-3','프랑크-헤르츠 실험','전자를 가속해 원자 기체와 충돌시키면 특정 에너지에서 비탄성충돌로 원자를 들뜨게 할 수 있다. 전자가 그 에너지를 잃으면 검출 전류가 줄고, 가속 전압을 더 높이면 비슷한 감소가 반복된다. 전류 곡선의 간격은 원자의 이산적인 들뜸 에너지와 연결되며, 전류 최소점의 절대 위치에는 접촉 전위도 영향을 준다.');
add('6-2-4-4','프랑크-헤르츠 실험의 모의실험','전자 에너지를 높이며 탄성충돌과 들뜸을 일으키는 비탄성충돌을 구별한다. 검출 앞의 지연 전위를 넘을 에너지가 남았는지에 따라 수집 전류가 달라진다. 가속 전압에 따른 전류 곡선과 충돌 위치를 함께 해석하고, 전압 간격과 준위 차이의 관계를 비교한다. 유한한 입자 수의 순간 요동은 평균 곡선과 구별한다.');
add('6-3-1-4','물질파의 고전적 극한','드브로이 파장은 운동량이 커질수록 짧아진다. 거시적인 물체에서는 이 파장이 실험의 길이 규모보다 매우 작아 간섭을 관찰하기 어렵다. 상자 속 입자의 양자수가 커지면 에너지 간격이 전체 에너지에 비해 작아질 수 있다. 고전적 극한은 모든 양자 상태가 한 개의 확정 궤적으로 곧바로 바뀐다는 뜻은 아니다.');
add('6-3-1-5','파동과 입자의 이중성','전자 같은 물질도 간섭하는 전파 진폭과 국소적인 검출 결과를 보인다. 한 번의 검출은 점처럼 나타나지만 많은 동일 준비의 결과에는 간섭 확률분포가 생긴다. 파동함수와 실제 물질 밀도를 동일시하지 말고 준비·전파·측정의 관계로 이해한다. 어느 경로 정보의 측정은 간섭 조건을 바꿀 수 있다.');
add('6-3-3-1','파동묶음과 입자','단일 파수의 평면파는 공간 전체에 퍼져 있으므로 국소화된 입자 상태를 나타내려면 여러 파수를 중첩해야 한다. 파수 범위를 넓히면 위치 분포를 좁힐 수 있고 운동량 불확정성은 커진다. 자유입자 파동묶음은 분산으로 퍼질 수 있다. 확률분포의 이동과 개별 측정에서의 입자 위치를 구별한다.');
add('6-3-5-4','1차원 상자에 갇힌 물질파','무한히 높은 벽으로 제한한 상자에서는 벽에서 파동함수가 0이고 내부의 정상 모드만 허용된다. 여러 모드를 합친 파동묶음은 벽에서 반사되며 모드별 위상 변화로 모양도 변한다. 고전 입자의 단순 왕복과 달리 분산과 간섭을 볼 수 있다. 확률의 전체 적분이 유지되는지 확인한다.');
add('6-3-5-5','고리에 갇힌 물질파','고리 위의 파동함수는 한 바퀴 뒤 같은 값을 가져야 하므로 주기 경계조건을 따른다. 이에 맞는 파수와 각운동량은 이산적으로 허용된다. 여러 진행 모드를 합치면 고리를 따라 이동하거나 퍼지는 확률분포를 만들 수 있다. 파동함수의 실수·허수 성분과 절댓값 제곱인 확률밀도를 구별한다.');
add('6-3-5-6','2차원 상자에 갇힌 물질파','직사각형 상자의 두 방향 경계조건을 만족하는 모드를 조합하면 2차원 입자 상태를 만든다. 국소화된 파동묶음은 벽에서 반사하고 여러 경로의 간섭으로 복잡한 분포를 형성한다. 확률밀도 무늬를 당구공의 확정 궤적과 동일시하지 않는다. 두 방향 길이와 초기 운동량을 바꾸어 모드 간격과 전파를 비교한다.');
add('6-4-1-1','양자역학','양자역학은 상태와 관측량을 각각 상태벡터와 연산자로 기술하고 측정 결과의 확률을 계산한다. 파동함수의 시간 변화는 슈뢰딩거 방정식으로 정해지지만 개별 측정값은 일반적으로 확정되지 않는다. 기대값·확률분포·한 번의 측정 결과를 구별해야 한다. 고전적인 초기 위치와 속도만으로 모든 상태를 지정하는 방식과 다르다.');
add('6-4-2-1','슈뢰딩거 방정식과 양자상태','주어진 해밀토니안과 초기 파동함수는 닫힌 계의 시간 변화를 결정한다. 퍼텐셜은 위치에 따른 위상과 전파를 바꾸고 운동에너지 연산자는 공간 곡률에 작용한다. 초기 상태는 정규화와 경계조건을 만족해야 한다. 시간에 의존하지 않는 퍼텐셜에서도 여러 에너지 상태의 중첩 확률밀도는 시간에 따라 변할 수 있다.');
add('6-4-2-1','슈뢰딩거 방정식의 구조와 해석','비상대론적 슈뢰딩거 방정식은 시간에 대해 1차, 공간에 대해 2차 미분이며 일반적으로 복소 파동함수를 사용한다. 소리의 실수 변위 파동방정식과 모양이 일부 비슷해도 해석은 다르다. 파동함수 자체보다 절댓값 제곱과 확률전류가 관측 확률을 연결하며, 전체 위상과 상대 위상의 물리적 역할도 구별한다.');
add('6-4-2-4','퍼텐셜 계단에 진입하는 파동묶음의 운동','퍼텐셜이 갑자기 달라지는 곳에 파동묶음이 도달하면 반사와 투과가 일어날 수 있다. 계단보다 에너지가 높아도 양자 반사가 가능하고 투과 부분의 파장과 속도는 달라진다. 묶음은 여러 에너지 성분을 포함하므로 단일 에너지 반사율과 정확히 같지 않을 수 있다. 반사·투과 확률은 밀도 적분과 전류로 평가한다.');
add('6-4-2-5','퍼텐셜 장벽에 진입하는 파동묶음의 운동','유한한 장벽에서는 에너지가 장벽보다 낮아도 반대편에 투과 확률이 남을 수 있다. 장벽 높이·폭·입사 에너지에 따라 터널링과 위상 변화가 달라진다. 확률밀도의 작은 꼬리와 실제로 반대편으로 흐르는 확률전류를 구별한다. 여러 에너지 성분의 반사·투과는 파동묶음의 모양을 바꿀 수 있다.');
add('6-4-2-7','분리된 파동묶음의 운동','하나의 입자 상태가 두 공간 영역에 걸쳐 나뉜 진폭을 가질 수 있다. 두 묶음이 다시 만나면 상대 위상에 따라 확률 간섭이 나타난다. 이는 한 입자가 두 고전 공으로 쪼개졌다는 뜻이 아니다. 혼합 상태의 두 독립 집단과 결맞은 중첩을 구별하고 전체 확률 정규화를 확인한다.');
add('6-4-2-8','파동묶음의 운동 모의실험','초기 파동묶음과 퍼텐셜을 정한 뒤 시간에 따른 확률밀도와 위상 변화를 비교한다. 평균 위치가 움직여도 분포 폭은 동시에 바뀔 수 있다. 수치계산에서는 격자 간격·시간 간격·경계 반사와 정규화 오차를 확인해야 한다. 격자를 촘촘하게 했을 때 물리적인 결과가 유지되는지 비교하는 것이 중요하다.');
add('6-4-3-3','2차원 파동묶음의 운동 모의실험','2차원 상태에서는 두 방향의 운동량과 퍼텐셜의 공간 형태가 전파를 결정한다. 장벽의 틈에서는 회절이 생기고 여러 경로가 만나면 간섭이 나타난다. 색으로 표현한 복소 위상과 높이로 표현한 확률밀도의 의미를 따로 읽는다. 유한한 계산 영역의 경계에서 생긴 반사와 실제 장애물의 산란을 혼동하지 않는다.');
add('6-4-4-1','물질파의 정상파','시간에 무관한 해밀토니안의 에너지 고유상태는 공간 함수에 하나의 시간 위상 인자를 곱한 형태다. 이 상태의 확률밀도는 시간에 따라 변하지 않는다. 그러나 정상상태가 언제나 확률전류 0이라는 뜻은 아니다. 구속된 실수 정상 모드와 진행하는 에너지 고유상태를 구별한다.');
add('6-4-4-3','비정상상태','서로 다른 에너지 고유상태를 중첩하면 각 성분이 다른 속도로 위상을 누적한다. 확률밀도에는 에너지 차이에 따른 시간 간섭항이 나타나 위치와 모양이 변할 수 있다. 중첩 계수의 절댓값 제곱은 각 에너지를 측정할 확률이며 위치 확률과 다르다. 한 고유상태만 남았을 때 시간 변화가 사라지는지 확인한다.');
add('6-4-4-5','퍼텐셜 계단 모의실험','단일 에너지의 입사 상태에서 계단 양쪽의 파수와 파동함수 경계조건을 맞춘다. 입사·반사·투과 진폭을 구한 뒤 각 영역의 속도를 포함하여 확률전류를 비교한다. 투과 진폭의 제곱만을 투과율로 읽으면 파수가 다른 경우 잘못된 결과를 얻는다. 장벽 위·아래 에너지에서의 해 형태를 나누어 관찰한다.');
add('6-4-4-6','터널효과','에너지가 퍼텐셜 장벽보다 낮아도 파동함수는 유한한 장벽 내부에서 감쇠하며 반대편까지 이어질 수 있다. 그 결과 고전적으로 통과하지 못하는 조건에서도 투과 확률이 생긴다. 장벽 폭과 높이가 커지면 보통 투과가 작아진다. 터널링은 입자가 에너지보존을 잠시 어긴다는 설명 없이 경계조건을 맞춘 양자 해로 이해할 수 있다.');
add('6-4-6-5','전자의 확률분포','수소 원자의 오비탈은 반지름과 각도에 의존하는 위치 확률밀도를 준다. 확률밀도 그림의 밝기와 반지름 구간에 포함될 확률은 다르며 후자에는 부피 요소가 필요하다. 마디는 파동함수가 0인 영역이다. 원자 그림의 덩어리나 표면은 확률분포의 표현이지 전자가 따라가는 궤도나 단단한 외벽이 아니다.');
add('6-4-7-1','시간에 무관한 슈뢰딩거 방정식의 수치해석','해석적으로 풀기 어려운 퍼텐셜에서도 격자화한 해밀토니안의 고유값과 고유벡터로 정상상태를 계산할 수 있다. 경계조건과 계산 영역을 먼저 정하고 공간 간격을 줄여 에너지와 파동함수의 수렴을 확인한다. 고유함수의 정규화와 서로 다른 상태의 직교성을 검사하며, 유한 영역이 연속 산란 상태에 주는 영향을 구별한다.');
add('6-4-7-3','정상상태의 수치해석 전략','속박 상태를 찾는 사격법에서는 시도 에너지를 정하고 한쪽 경계에서 방정식을 적분해 다른 경계 조건을 만족하는지 확인한다. 에너지를 바꾸며 잔차의 부호와 마디 수를 추적할 수 있다. 큰 값으로 발산하는 수치해를 물리 상태로 오인하지 않도록 정규화와 적분 방향을 조절하고, 격자와 영역을 바꾸어 확인한다.');
add('6-4-7-6','3차원의 중심력장의 수치해석','중심력 퍼텐셜에서는 각도 부분을 구면조화함수로 분리하고 방사 방향의 방정식을 수치적으로 풀 수 있다. 유효 퍼텐셜에는 각운동량에 따른 원심 항이 들어간다. 원점의 규칙성과 먼 거리의 속박 조건을 적용하고, 방사 함수와 실제 반지름 구간 확률의 차이를 부피 요소로 확인한다.');
add('6-4-8-1','3차원 상자에 갇힌 파동묶음의 운동','직육면체 상자의 고유 모드는 세 방향의 정상 모드를 곱해 구성할 수 있다. 초기 파동묶음을 이 모드들로 분해한 뒤 각 에너지의 시간 위상을 더하면 운동을 얻는다. 벽에서의 반사와 내부 간섭 때문에 확률분포가 복잡해질 수 있다. 포함한 모드 수를 늘려 초기 분포와 시간 변화를 얼마나 잘 표현하는지 확인한다.');
add('6-4-8-3','수소원자에서 파동묶음의 운동','수소 원자의 여러 에너지·각운동량 고유상태를 중첩하면 시간에 따라 변하는 전자 확률분포를 만들 수 있다. 각 성분의 에너지 차이가 상대 위상의 변화율을 정한다. 확률 봉우리가 핵 주변을 움직여도 하나의 전자가 고전 궤도를 그대로 따른다고 결론내리지 않는다. 속박 상태만 포함한 전개와 연속 상태까지 필요한 초기 상태를 구별한다.');
add('6-5-1-3','배타원리','동일한 페르미온 두 개는 모든 양자수가 같은 한 입자 상태를 동시에 차지할 수 없다. 전자에서는 공간 오비탈뿐 아니라 스핀 상태까지 포함해야 하므로 같은 공간 오비탈에 서로 다른 스핀의 두 전자가 들어갈 수 있다. 이 원리는 원자 전자 배열과 물질의 안정성에 중요하며 단순한 전기적 반발력과는 다른 양자적 제약이다.');
add('6-5-1-3','쌓음원리','원자의 바닥상태 전자 배열은 배타원리와 상호작용을 고려하여 전체 에너지가 낮아지는 방향으로 채워진다. 독립 오비탈을 낮은 순서로 채우는 쌓음원리는 유용한 근사지만 다전자 상호작용 때문에 예외가 있다. 오비탈 순서를 수소의 에너지만으로 정하지 않고 차폐·전자 간 반발·스핀 배치의 영향을 함께 본다.');
add('6-5-1-4','페르미온과 보손','동일 입자를 교환할 때 상태의 대칭성에 따라 보손과 페르미온을 구별한다. 상대론적 양자 이론에서 정수 스핀은 보손, 반정수 스핀은 페르미온과 연결된다. 페르미온에는 배타원리가 적용되고 보손은 같은 상태를 함께 점유할 수 있다. 합성 입자는 구성과 전체 스핀에 따라 저에너지에서 둘 중 하나로 행동할 수 있다.');
add('6-5-2-1','주기율표','주기율표는 원자번호 순으로 원소를 배열하고 비슷한 바깥 전자 구조를 가진 원소를 같은 족으로 묶는다. 주기성은 전자껍질과 오비탈이 채워지는 양자 구조에서 나온다. 원자량 자체가 원소를 정의하는 것은 아니며 동위원소가 있어도 원자번호는 같다. 같은 족의 유사성과 각 원소의 차이를 함께 비교한다.');
add('6-5-2-4','주기율표와 원자의 분류','알칼리 금속·할로젠·비활성기체와 같은 분류는 주로 바깥 전자의 배열과 화학적 성질을 반영한다. 전이 원소에서는 내부 d 상태의 채움도 중요하다. 족을 따라 원자 크기와 이온화 경향이 바뀌는 이유를 핵전하 증가와 전자 차폐로 비교한다. 주기율표의 위치만으로 모든 물성을 정확히 예측할 수는 없다.');
add('6-6-1-1','분자결합','두 원자가 가까워졌을 때 전자와 핵의 전체 에너지가 떨어진 원자보다 낮아지면 결합 상태가 가능하다. 너무 가까우면 반발과 배타 효과가 커져 유한한 평형 거리가 생긴다. 이온결합·공유결합 등은 전하 분포를 이해하는 모형이며 실제 결합은 여러 성질을 함께 가질 수 있다. 결합에너지와 결합 길이는 서로 다른 양이다.');
add('6-6-1-2','공유결합','공유결합에서는 전자가 두 원자 주변에 퍼진 상태를 이루어 전체 에너지를 낮출 수 있다. 원자 오비탈의 선형결합은 결합성·반결합성 상태를 만들며, 어떤 상태가 얼마나 채워지는지가 결합을 정한다. 단순히 전자 하나가 두 원자를 기계적으로 묶는 그림보다 양자 상태와 전체 에너지의 비교가 필요하다.');
add('6-6-1-3','전자의 분포와 결합','방향성을 가진 p·d 오비탈과 이들의 혼성은 분자의 결합 방향과 기하학적 모양을 이해하는 데 도움을 준다. 전자 밀도는 핵 사이 결합과 비결합 전자쌍에 따라 달라진다. 오비탈의 그림과 측정 가능한 전체 밀도를 구별하며, 하나의 오비탈 모양만으로 분자 구조 전체를 확정하지 않는다.');
add('6-6-1-4','공유결합 모의실험','두 퍼텐셜 우물을 가까이하면 각 우물의 고립 상태가 서로 섞여 에너지 분열을 만든다. 대칭·반대칭 상태의 에너지와 확률밀도를 비교하면 결합성과 반결합성을 이해할 수 있다. 1차원 모형은 상태 중첩 원리를 보여 주지만 실제 분자의 3차원 전자 구조와 핵 사이 반발을 모두 포함하지는 않는다.');
add('6-6-2-3','분자의 여러 진동모드','여러 원자의 작은 변위는 정상 모드로 분해할 수 있다. 선형 분자는 원자 수의 세 배에서 다섯, 비선형 분자는 여섯을 뺀 수의 진동 자유도를 가진다. 뻗기와 굽히기 모드의 진동수는 질량과 힘상수에 의존한다. 대칭성은 적외선·라만 신호에 나타나는 모드를 정하며 굽힘 모드의 축퇴도 구별한다.');
add('6-8-1-1','고체의 형성','원자들이 안정한 평균 위치 주변에서 진동하며 장시간 이웃 구조를 유지하면 고체의 성질이 나타난다. 주기적인 배열은 결정, 장거리 주기성이 없는 구조는 비정질 고체다. 낮은 온도에서도 원자는 완전히 정지하지 않으며 양자 영점운동이 남을 수 있다. 상호작용과 냉각 과정은 형성되는 구조를 함께 정한다.');
add('6-8-1-2','이온결합 결정','양·음 이온이 반복 배열되면 많은 이웃과의 쿨롱 상호작용으로 결정이 안정해진다. 한 이온의 주변 배위와 전체 격자의 에너지를 함께 고려해야 하므로 독립된 분자 쌍만으로 설명하기 어렵다. NaCl형과 CsCl형은 배위와 단위세포가 다르다. 가까운 거리의 반발은 이온이 무한히 접근하는 것을 막는다.');
add('6-8-1-3','공유결합 결정','공유결합이 공간 전체로 이어지면 방향성 있는 원자 네트워크가 만들어진다. 다이아몬드와 흑연은 같은 탄소라도 결합 배열이 달라 강도와 전기적 성질이 다르다. 원소 종류만 아니라 결합 구조와 전자의 비편재화도 물성을 정한다. 층 안과 층 사이 결합의 차이를 따로 살펴보자.');
add('6-8-1-6','원소들의 결정구조','체심입방·면심입방·육방밀집 구조는 여러 원소에서 나타나는 대표적인 원자 배열이다. 단위세포의 꼭짓점·면·중심에 놓인 원자의 공유 비율을 세어 세포당 원자 수를 구한다. 배위수와 채움률은 구조에 따라 다르며 같은 원소도 온도와 압력에 따라 구조가 바뀔 수 있다.');
add('6-8-2-1','주기적인 퍼텐셜에서의 양자상태','결정의 주기 퍼텐셜에서는 전자 상태가 블로흐 형식으로 표현되고 허용 에너지가 띠를 이룬다. 여러 원자의 고립 준위가 서로 결합해 분열되는 과정으로 띠의 형성을 이해할 수 있다. 유한한 원자 수의 촘촘한 준위와 무한 주기계의 연속 띠를 구별하며, 상태의 공간 분포도 함께 비교한다.');
add('6-8-2-3','에너지띠와 전도성','전자 전도는 띠의 존재뿐 아니라 띠가 얼마나 채워졌는지와 페르미 준위 주변에 이동 가능한 상태가 있는지에 달려 있다. 완전히 채워진 띠와 큰 틈을 가진 계는 작은 장에서 전도가 제한된다. 부분적으로 채워진 띠는 금속적 응답을 만들 수 있다. 산란·온도·불순물도 실제 전도도를 결정한다.');
add('6-8-3-3','크로니그-페니 모형의 양자상태','반복되는 계단형 퍼텐셜은 결정의 허용 에너지띠와 금지 틈을 설명하는 단순한 모형이다. 주기마다 파동함수와 기울기를 연결하고 블로흐 조건을 적용하면 허용 범위를 얻는다. 고리 모형에서는 주기 경계조건에 맞는 이산 파수가 선택된다. 장벽 높이와 폭을 바꾸어 띠가 갈라지는 과정을 비교한다.');
add('6-8-4-1','반도체','반도체는 채워진 원자가띠와 비어 있는 전도띠 사이의 틈 때문에 운반자 수가 온도·조명·도핑에 민감하다. 전도띠의 전자와 원자가띠의 정공이 전류에 기여한다. 반도체 여부를 하나의 고정된 띠틈 숫자만으로 분류하지 않으며 구조·전이·산란도 중요하다. 전자와 정공을 서로 다른 실제 기본입자라고 해석하지 않는다.');
add('6-8-4-2','도핑된 반도체','소량의 불순물을 넣으면 전자를 제공하는 도너나 전자를 받는 억셉터 준위가 생길 수 있다. n형은 전자가, p형은 정공이 다수 운반자인 경우다. 불순물 이온까지 포함하면 보통 물질의 전체 전하는 거의 중성이다. 온도에 따른 이온화와 보상 도핑 때문에 첨가한 원자 수가 항상 자유 운반자 수와 같지는 않다.');
add('6-8-4-4','주기성이 일부 깨어진 격자 퍼텐셜','불순물이나 결함은 주기 퍼텐셜을 국소적으로 바꾸어 띠틈 안의 국소 상태나 산란을 만들 수 있다. 결함의 세기와 위치에 따라 파동함수의 분포와 에너지가 달라진다. 완전 주기계의 띠와 결함 상태를 비교하며, 하나의 결함 모형에서 나타난 결과를 모든 실제 도핑 구조에 그대로 적용하지 않는다.');
add('7-1-1-1','원자모형과 핵','원자의 전자는 넓은 영역에 분포하지만 양전하와 대부분의 질량은 매우 작은 핵에 집중된다. 산란 실험은 이 공간 규모 차이를 드러냈다. 핵은 양성자와 중성자로 구성되며 원자번호와 질량수로 구별된다. 전자 상태를 결정하는 전자기 상호작용과 핵자를 결합시키는 핵력은 서로 다른 작용이다.');
add('7-1-1-2','미지의 방사선','베릴륨 등에서 나온 투과력이 큰 중성 방사선이 가벼운 원자핵을 튕겨 내는 결과는 중성자의 발견으로 이어졌다. 운동량과 에너지 전달을 비교하면 질량 없는 광자만으로 설명하기 어려운 점을 확인할 수 있다. 중성자는 전하가 없지만 질량과 자기모멘트를 가지며 원자핵의 구성 요소다.');
add('7-1-1-5','핵자기공명','스핀과 자기모멘트를 가진 핵은 자기장에서 에너지 준위가 갈라진다. 그 차이에 맞는 고주파 장을 가하면 공명 전이가 일어날 수 있다. 전자에 의한 차폐 때문에 공명 주파수는 핵 주변의 화학 환경에도 의존한다. 공명 주파수와 이완 시간을 통해 구조 정보를 얻으며 모든 핵종이 같은 방식으로 신호를 주지는 않는다.');
add('7-1-1-6','중간자','중간자는 쿼크와 반쿼크가 결합한 강입자의 한 종류다. 핵자 사이의 잔여 강한 상호작용은 저에너지에서 파이온 교환 등의 유효 모형으로 설명할 수 있다. 이를 기본 강한 상호작용의 매개입자인 글루온과 구별해야 한다. 중간자의 전하·스핀·질량과 붕괴 방식은 종류마다 다르다.');
add('7-1-2-1','안정된 핵','원자핵의 안정성은 짧은 범위의 핵력, 양성자 사이 쿨롱 반발, 배타원리와 양자껍질 구조의 경쟁으로 정해진다. 가벼운 안정 핵은 양성자·중성자 수가 비슷하지만 무거운 핵에서는 더 많은 중성자가 필요하다. 결합된 핵이라고 모두 방사성 붕괴에 대해 안정한 것은 아니므로 가능한 딸핵의 에너지와 비교해야 한다.');
add('7-1-2-3','핵자당 결합에너지','핵자당 결합에너지는 전체 결합에너지를 핵자 수로 나눈 값이다. 중간 질량의 철·니켈 부근에서 큰 값을 가지므로 가벼운 핵의 융합과 매우 무거운 핵의 분열은 에너지를 방출할 수 있다. 실제 반응의 에너지는 초기와 최종 질량을 정확히 비교해야 한다. 평균 결합에너지 하나만으로 모든 핵종의 붕괴 가능성을 판정하지 않는다.');
add('7-1-2-6','두 핵자의 결합상태','두 핵자의 결합은 스핀·이소스핀 상태와 핵력의 형태에 의존한다. 양성자와 중성자로 된 중수소핵은 약하게 결합하지만 두 양성자나 두 중성자는 자유 공간에서 같은 방식의 안정한 결합 상태를 만들지 않는다. 짧은 거리의 상호작용을 단순한 상자 퍼텐셜로 근사할 수 있어도 실제 텐서 성분과 스핀 의존성을 모두 대체하지는 못한다.');
add('7-2-1-1','핵의 붕괴','불안정한 핵은 입자나 광자를 방출하여 다른 핵종이나 낮은 에너지 상태로 변할 수 있다. 알파·베타·감마 과정은 방출 성분과 핵의 변화가 다르다. 각 과정에서 전하·에너지·운동량과 필요한 양자수가 보존된다. 개별 붕괴 시각을 정해 예측하기보다 동일한 핵 집단의 확률과 평균 감소를 계산한다.');
add('7-2-1-3','반입자','입자와 반입자는 같은 질량과 스핀을 가지며 전하 등 일부 양자수가 반대다. 양전자는 전자의 반입자다. 입자–반입자의 소멸에서는 에너지가 없어지는 것이 아니라 다른 입자나 광자로 전환된다. 전하가 0인 입자도 반입자가 따로 있을 수 있으므로 전하 부호만으로 모든 경우를 구별하지 않는다.');
add('7-2-1-4','약한상호작용','베타붕괴는 약한상호작용으로 핵 안의 양성자와 중성자의 구성이 바뀌는 과정이다. 전자나 양전자와 함께 중성미자 또는 반중성미자가 에너지·운동량을 나누어 갖는다. 그래서 전자의 에너지가 연속적으로 분포할 수 있다. 핵자를 결합시키는 잔여 강한 상호작용과 붕괴 전이를 일으키는 약한상호작용을 구별한다.');
add('7-2-2-1','방사성붕괴법칙','일정한 붕괴상수를 가진 동일한 핵종에서는 단위 시간의 붕괴 확률이 남아 있는 각 핵에 같게 적용된다. 많은 핵의 평균 개수는 지수적으로 감소하고 반감기는 초기 개수와 무관하다. 방사능은 남은 개수에 붕괴상수를 곱한 값이다. 개별 핵이 반감기만큼 살도록 예정되어 있다는 뜻은 아니다.');
add('7-2-2-3','핵의 붕괴법칙과 생존곡선','지수 생존곡선은 살아남은 시간과 무관하게 같은 위험률을 갖는 과정의 특징이다. 핵의 지수 붕괴와 달리 생물의 사망 위험은 나이와 환경에 따라 변할 수 있다. 두 곡선을 같은 반감기 하나로 설명하지 않고 시간별 위험률을 비교해야 한다. 유한한 집단의 실제 개수는 매끈한 평균 곡선 주변에서 요동한다.');
add('7-2-2-3','핵의 붕괴법칙 모의실험','각 시간 간격마다 남아 있는 핵에 같은 붕괴 확률을 적용해 개수의 변화를 기록한다. 여러 실행을 평균하면 지수 곡선에 가까워지고 개수가 적으면 요동이 더 뚜렷하다. 시간 간격을 바꿀 때 확률도 일관되게 바꾸어야 한다. 반감기와 붕괴상수의 관계를 측정하고 딸핵까지 붕괴하는 연속 과정은 별도로 구별한다.');
add('7-2-6-1','4개의 자연 방사성 계열','알파붕괴는 질량수를 네 줄이고 베타붕괴는 질량수를 유지하므로 붕괴 사슬은 질량수를 네로 나눈 나머지에 따라 네 계열로 묶을 수 있다. 긴 반감기의 어미핵은 짧은 반감기의 딸핵을 계속 공급한다. 네프투늄 계열을 다른 장수명 자연 계열과 같은 양으로 현재 남아 있는 계열이라 해석하지 않도록 기원을 구별한다.');
add('7-3-2-2','핵분열의 발견과 이를 이용한 폭탄의 제조','무거운 핵이 더 작은 핵들로 나뉠 수 있다는 발견은 핵 결합에너지에 대한 이해를 바꾸었다. 이후 이 원리는 발전과 무기에 각각 이용되며 역사와 사회에 큰 영향을 주었다. 여기서는 발견의 의미와 에너지보존을 살펴본다. 분열 전후 질량 차이는 생성물의 운동에너지와 복사 에너지 등으로 나타난다.');
add('7-3-2-2','연쇄반응','어떤 분열에서 나온 중성자가 이후의 분열에 기여하면 반응이 여러 세대로 이어질 수 있다. 각 세대에서 후속 반응이 평균적으로 늘어나는지 줄어드는지가 거시적인 변화 양상을 정한다. 중성자의 손실과 흡수도 경쟁한다. 이 개념은 반응의 통계적 이어짐을 설명하며 실제 장치의 조건을 단순한 개수 증가 모형만으로 결정하지 않는다.');
add('7-3-2-3','핵분열의 연쇄반응 모의실험','추상적인 분기 모형에서 한 사건이 몇 개의 후속 사건을 만드는지 확률적으로 정하면 증가·유지·소멸 양상을 비교할 수 있다. 같은 평균 조건이라도 유한한 초기 집단에서는 우연히 사슬이 끊길 수 있다. 여러 실행의 평균과 한 실행의 요동을 따로 읽는다. 이 모형은 개념적 세대 변화를 나타내며 실제 원자로의 설계나 반응 동역학을 대체하지 않는다.');
add('7-3-3-1','핵융합','가벼운 핵이 결합해 더 안정한 생성물로 바뀌면 질량 차이에 해당하는 에너지가 방출될 수 있다. 양전하 핵끼리 접근하려면 쿨롱 반발과 경쟁해야 하며 양자 터널링도 반응에 기여한다. 모든 가벼운 핵의 조합이 같은 반응률을 갖지는 않는다. 에너지 방출 가능성과 실제로 충분한 반응을 지속하는 조건을 구별한다.');
add('7-3-3-3','CNO 순환과정','CNO 순환은 탄소·질소·산소 핵을 매개로 수소가 헬륨으로 바뀌는 별 내부의 반응 사슬이다. 매개 핵은 순환 후 다시 돌아오며 순 결과에는 에너지와 중성미자 방출이 포함된다. 온도가 높을수록 상대적인 기여가 커져 더 무거운 별에서 중요하다. 별 전체의 에너지 생산은 온도·밀도·조성에 따라 다른 경로와 경쟁한다.');
add('7-4-2-1','원자력 발전','원자력 발전은 핵반응에서 나온 에너지를 열로 회수하고 발전계로 전달해 전기를 생산한다. 핵반응 영역과 열을 일로 바꾸는 터빈 계통은 서로 다른 역할을 가진다. 출력 제어뿐 아니라 냉각과 잔열 제거가 중요하다. 발전 효율·연료 과정·폐기물 관리는 각각 별도의 물리적·공학적 문제로 평가해야 한다.');
add('7-4-2-5','토카막','토카막은 도넛 모양의 공간에서 자기장으로 고온 플라스마를 가두는 장치다. 토로이달장과 폴로이달장이 결합한 나선형 구조가 입자의 손실을 줄이는 데 기여한다. 실제 플라스마에는 수송·불안정성과 열 손실이 있어 단일 입자의 자력선 추적만으로 가둠을 설명할 수 없다. 가열한 에너지와 융합으로 얻은 에너지를 구별한다.');
// Display equations accompany the independently rewritten explanations.
